window.COURSES=[{"C_ID": "374", "C_TITLE": "UAL Level 3 Diploma and Extended Diploma in Creative Practice: Fashion Design", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>UAL Level 3 Diploma and Extended Diploma in Creative Practice: Fashion Design</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This fashion and textiles course equips you with industry-standard techniques and practical skills using professional workshops, studio and digital design software. You&rsquo;ll be taught by experience industry professionals to develop your creative vision through:&nbsp;</p>\n\n<ul>\n\t<li><strong>Fashion and costume research</strong> &ndash; become competent researching the history of fashion and costume and how to use this to inspire your own designs&nbsp;</li>\n\t<li><strong>Fashion design and construction&nbsp;</strong>&ndash; learn how to design, pattern cut and construct unique garments, from concept to finished product&nbsp;&nbsp;</li>\n\t<li><strong>Costume design and construction</strong> &ndash; Understand and practice the specialist skills required in costume design, construction, embellishment and performance&nbsp;&nbsp;</li>\n\t<li><strong>Textile design</strong> &ndash; from initial ideas to final designs &ndash; tell a story through textile designs using a variety of mediums&nbsp;</li>\n\t<li><strong>Props for theatre &amp; film&nbsp;</strong>&ndash; learn prop-making techniques for stage and screen productions&nbsp;</li>\n\t<li><strong>Digital design&nbsp;</strong>&ndash; build a portfolio of styling, branding and visual storytelling using Adobe Creative Cloud&nbsp;</li>\n\t<li><strong>Sustainability in fashion &amp; costume&nbsp;</strong>&ndash; discover how to work as an ethical, environmentally conscious designer&nbsp;</li>\n</ul>\n\n<p>Through lectures, workshops, industry briefs and live projects, you&rsquo;ll refine your craft in our specialist sewing, textile and prop-making workshops, photography studios and IT suites.&nbsp;</p>\n\n<p><strong>Industry Experience &amp; Enrichment&nbsp;</strong></p>\n\n<p>We believe in hands-on experience, giving you the chance to:&nbsp;</p>\n\n<ul>\n\t<li>Work on live industry briefs, designing costumes and props for theatrical productions and fashion editorials&nbsp;</li>\n\t<li>Exhibit your work in professional showcases&nbsp;&nbsp;</li>\n\t<li>Collaborate with industry professionals, gaining insight from guest speakers and theatre practitioners, including Chelmsford Theatre&nbsp;</li>\n\t<li>Create your own professional website and brand identity to launch your career&nbsp;</li>\n</ul>\n\n<p><strong>We also offer exciting field trips, with past experiences including:&nbsp;</strong></p>\n\n<ul>\n\t<li>Theatre shows, backstage and costume department tours&nbsp;</li>\n\t<li>Harry Potter Studio Tour &amp; cinema screenings&nbsp;</li>\n\t<li>Visits to The Fashion &amp; Textile Museum and The Victoria &amp; Albert Museum&nbsp;</li>\n\t<li>Leading London exhibitions and galleries&nbsp;</li>\n</ul>", "C_EMPLOYABILITY": "<p>This course prepares you for a diverse range of careers in the fashion, costume, and creative industries, equipping you with highly sought-after skills. Whether you want to go straight into employment, start your own business or continue studying, you&rsquo;ll have plenty of options, including:&nbsp;</p>\n\n<ul>\n\t<li>Entry-level job roles, apprenticeships or freelance work in fashion design, costume design, theatre prop-making, styling, branding and digital marketing&nbsp;</li>\n\t<li>Progressing to Level 4 in Creative Enterprise &ndash; delivered at Chelmsford College&nbsp;</li>\n\t<li>UCAS-recognised qualification, enabling you to apply for BA degree courses in Fashion, Costume Design, Theatrical Arts, Creative Direction, Set &amp; Prop Design and many more&nbsp;</li>\n</ul>\n\n<p>This course is your pathway into the world of fashion, theatre, and creative storytelling &mdash; are you ready to bring your vision to life?&nbsp;</p>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4, including English or Maths&nbsp;<strong>OR </strong>successful achievement at a<strong>&nbsp;</strong>relevant Level 2 vocational course</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Internally assessed course work and portfolio&nbsp;</p>", "C_FEES": "<p>&pound;150</p>", "C_ADDITIONALFEES": "<p>There may be educational activities throughout the year and these costs will be payable when&nbsp;necessary.&nbsp;</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk&nbsp;</p>", "C_METADESC": "", "C_SEOTITLE": "UAL Level 3 Diploma and Extended Diploma in Fashion Textiles", "C_SEOH1": "UAL Level 3 Extended Diploma in Fashion & Textiles", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Do you want to work in fashion design, textiles, costume, fashion styling, wardrobe assistant, merchandising or theatre prop-making? If so, this fashion diploma is for you!&nbsp;</p>\n\n<p>Equivalent to three A Levels, our Fashion &amp; Textiles course is developed to teach you how to create visually captivating designs that bring fashion and performance to life. You&rsquo;ll explore fashion and textile design, costume creation and theatrical prop-making, developing the skills to produce bold, innovative and engaging visual concepts for the runway, stage and screen.&nbsp;&nbsp;</p>\n\n<p>Whether you&rsquo;re interested in designing for a fashion brand, working behind the scenes in theatre or creating iconic props and costumes for film and TV, this textiles diploma provides the essential skills to help you break into the industry.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:40:54", "C_CREATEDBY": "16706593", "C_UPDATED": "00:25:41", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "472", "C_TITLE": "NCFE Diploma in Travel and Tourism, Level 2", "C_SECTION": "21", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>NCFE Level 2 Diploma in Travel and Tourism&nbsp;</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "32770PD", "C_SHORTCODE": "097", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The units studied are:&nbsp;</p>\n\n<ul>\n\t<li>Unit 1 Customer Service in travel destinations&nbsp;&nbsp;</li>\n\t<li>Unit 2 The UK travel and tourism industry&nbsp;&nbsp;</li>\n\t<li>Unit 5 UK Purpose Built Visitor Attractions&nbsp;</li>\n\t<li>Unit 4 Promotion in travel and tourism &nbsp;</li>\n\t<li>Unit 6 Understanding package holidays &nbsp;&nbsp;</li>\n\t<li>Unit 12 Tourism in a popular UK region&nbsp;</li>\n\t<li>Unit 11 impact of travel and tourism &nbsp;&nbsp;</li>\n\t<li>Unit 8 Hospitality in travel and tourism&nbsp;</li>\n</ul>\n\n<p><strong>Work Experience&nbsp;</strong></p>\n\n<p>Learners will undertake a minimum of 30 hours work experience on each year of a study programme at Chelmsford College, with an external organisation that meets the industry / sector specific requirements. Learners will need to seek these placements independently and can also seek support of their personal tutor and stakeholder engagement team.&nbsp;</p>\n\n<p><strong>Visits and Vocational activities</strong><br />\nTravel and&nbsp;Tourism is an active course, out and about making contact with employers in the sector for training, educational insight and experience. Some examples of the activities carried out are:</p>\n\n<ul>\n\t<li>Stansted Aerozone training day.</li>\n\t<li>Airline training day (Virgin Atlantic / British Airways).</li>\n\t<li>Local attractions/business research activities.</li>\n\t<li>City day breaks (insight to tourism).</li>\n\t<li>Aviation experience.</li>\n\t<li>Team building activities.</li>\n</ul>", "C_EMPLOYABILITY": "<p>On successful completion of the Level 2 course, you can progress onto the Level 3 qualification in Travel and Tourism or related subjects. You could also go into employment or apply for an Apprenticeship.</p>", "C_ELIGIBILITY": "<p>2 GCSEs at grades 9-3 or successful achievement of a Level 1 vocational course&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>This course is assessed by a range of assignment work that can take place in the form of Presentations, Reports, Practical Role Play Assessments, Mock Scenarios as well as Observations of Practice.&nbsp;</p>", "C_FEES": "", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p><a href=\"mailto:information@chelmsford.ac.uk\">c</a>areersadvicezone@chelmsford.ac.uk&nbsp;</p>", "C_METADESC": "<p>To provide opportunities for full time learners to achieve a broad based understanding of the travel and tourism industry. To provide opportunities for learners to focus on the development of the major key skills in a travel and tourism context.</p>", "C_SEOTITLE": "Level 2 Diploma in Travel & Tourism | Chelmsford College", "C_SEOH1": "Level 2 Diploma in Travel & Tourism", "C_SEOH2": "NCFE Level 2 Travel & Tourism Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This Travel and Tourism course is designed to provide you with the key knowledge and basic principles of the&nbsp;Travel and Tourism sector as well as directly engaging in the Aviation Environment of Airport Operations. You will gain the essential knowledge and boost your skills to meet the changing needs of the rapidly growing industry. Whilst providing you with a strong foundation, this course will help to improve your confidence to work towards careers in travel agents, customer service-based roles, holiday resorts, and airports, or access to a higher-level qualification.</p>", "C_YEAR": "", "C_CREATED": "00:54:12", "C_CREATEDBY": "83439040", "C_UPDATED": "00:20:07", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Travel & Tourism", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "482", "C_TITLE": "UAL Level 3 Diploma and Extended Diploma in Creative Practice: Graphic Design", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>UAL Level 3 Diploma and Extended Diploma in Creative Practice: Graphic Design</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "99999", "C_SHORTCODE": "080", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>To join this graphic design course, it is not essential to know the Adobe Creative Suite, as we teach you this throughout. You will be taught Adobe Photoshop, Illustrator, InDesign, Premiere Pro and more.</p>\n\n<p>Additionally, you will undertake a variety of creative projects; these will explore how to professionally design to an industry standard while working on industry briefs throughout your course. Most importantly, these projects have been designed to enable you to build the best possible portfolio to take to University and job interviews after completing your Level 3 with us.</p>\n\n<p>Lastly, this course has a strong connection to the design industry, where you will be able to gain work experience to build an impressive portfolio. This is important as it enables you to experience the industry during your study as well as experience to add to your CV.</p>\n\n<p>Other notable aspects about this course include:</p>\n\n<ul>\n\t<li>Computers and industry standard software, such as Adobe</li>\n\t<li>Access to photo studios, print rooms, and other creative media facilities</li>\n\t<li>Real industry briefs and projects &ndash; Such as Coca-Cola, Penguin Books and D&amp;AD</li>\n\t<li>Work experience with real design companies and professionals</li>\n\t<li>University visits and progression guidance</li>\n\t<li>Taught by industry professionals</li>\n</ul>", "C_EMPLOYABILITY": "<p>&nbsp;</p>\n\n<ul>\n\t<li>University to study a degree</li>\n\t<li>Employment</li>\n\t<li>Level 4 Media</li>\n\t<li>Higher level apprenticeship</li>\n\t<li>Degree apprenticeships&nbsp;</li>\n</ul>\n\n<p>&nbsp;</p>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4 including English or Maths OR successful achievement at a relevant Level 2 vocational course</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Final Major Project</p>", "C_FEES": "<p>&pound;75</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p><a href=\"mailto:information@chelmsford.ac.uk\">information@chelmsford.ac.uk</a></p>", "C_METADESC": "", "C_SEOTITLE": "Level 3 Diploma and Extended Diploma in Creative Media Production & Technology (Graphic Design)", "C_SEOH1": "Creative Media Production Level 3 Diploma in Graphic Design Essex | Chelmsford College", "C_SEOH2": "Full Time Graphic Design Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This course is for creative and free-thinking individuals who have an aspiration to create logos, posters, advertising, motion graphics, packaging, social media marketing, print media, and upcoming developments, such as mobile apps, as well as designing for live industry briefs.</p>\n\n<p>Furthermore, you will be taught by industry professionals who have university and industry connections. Graphic and Digital Design will teach you up-to-date creative skills that you will need to stand out at interviews, gain the knowledge to join the creative industry and develop your creative thinking to a professional standard.</p>", "C_YEAR": "", "C_CREATED": "00:38:05", "C_CREATEDBY": "83439040", "C_UPDATED": "00:27:29", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "483", "C_TITLE": "City & Guilds Diploma in Professional Cookery, Level 2", "C_SECTION": "14", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>City &amp; Guilds Level 2 Diploma in Professional Cookery</p>", "C_ADDITIONALQUALS": "<p>You will study Life Skills and also continue to study a maths and English qualification if you have not achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>\n\n<p>We also work closely with a range of&nbsp; stakeholders, including City &amp; Guilds and The New London Restaurant, to improve our cookery programmes based on their feedback.</p>", "C_COURSECODE": "32971FT", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>To ensure that you are competent in Professional Cookery, this course includes a minimum of 30 hours work related experience and covers various units, enabling a thorough understanding.</p>\n\n<p>Units studied are:</p>\n\n<ul>\n\t<li>Health and safety in catering and hospitality</li>\n\t<li>Food safety</li>\n\t<li>Legislation in food and beverage service</li>\n\t<li>Prepare and cook meat and offal</li>\n\t<li>Prepare and cook fish and shellfish</li>\n\t<li>Prepare and cook fruit and vegetables</li>\n\t<li>Prepare and cook poultry</li>\n\t<li>Prepare and cook stocks, soups and sauces</li>\n\t<li>Principles of customer service in hospitality, leisure and travel and tourism</li>\n\t<li>Giving customers a positive impression</li>\n\t<li>Food service</li>\n\t<li>Investigate the catering and hospitality industry</li>\n</ul>", "C_EMPLOYABILITY": "<ul>\n\t<li>Progression to further study could include the Level 3 Advanced Professional Cookery apprenticeship, or&nbsp;the Technical Diploma or&nbsp;Diploma in Professional Cookery.</li>\n\t<li>If you would prefer to enter employment, career opportunities may include positions as a Commis Chef, Junior Chef de Partie.</li>\n</ul>", "C_ELIGIBILITY": "<p>3 GCSEs grades 9-3 in English and Maths and 1 other or a Level 1 qualification in Catering.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>This course is assessed throughout the year by knowledge tests and practical assessments within our production kitchen and practical workshops.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>Approximately &pound;200</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk&nbsp;</p>", "C_METADESC": "", "C_SEOTITLE": "Level 2 NVQ Diploma in Professional Cookery Essex | Chelmsford College", "C_SEOH1": "", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This Professional Cookery course is highly recognised by employers; by completing this one-year course, you will gain qualifications to become a professional within the hospitality and catering industry. This programme meets the needs of learners who work or want to work as professional chefs in the catering and hospitality sectors. The varied course content allows learners to learn, develop and practise the skills required for employment and/or career progression in the catering and hospitality sector.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:13:57", "C_CREATEDBY": "83439040", "C_UPDATED": "00:22:45", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Catering", "levels": ["Intermediate (Level Two)"], "funding": ["16-18"]}, {"C_ID": "489", "C_TITLE": "NCFE for Entry to the Uniformed Services, Level 2", "C_SECTION": "17", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>NCFE Level 2 Diploma for Entry to the Uniformed Services</p>", "C_ADDITIONALQUALS": "<p>You will study Life Skills and continue to study a maths and English qualification if you have not achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>\n\n<p>We collaborate with stakeholders, including Essex Air Ambulance and Essex Police, to enhance our Public Services courses based on industry feedback.</p>\n\n<p><strong>Please note that the above addition may only apply to specific Public Services programmes.</strong></p>", "C_COURSECODE": "31472PD", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>To ensure you have a throughout understanding of the industry ready for entry to the workforce, all learners will study the following units:</p>\n\n<ul>\n\t<li>Public Service Skills &amp; Support for the Community</li>\n\t<li>Employment in Uniformed Public Services</li>\n\t<li>Health &amp; Fitness for Entry into the Uniformed Public Services</li>\n\t<li>Volunteering&nbsp;</li>\n\t<li>Activities &amp; Teamwork for the Public Services</li>\n\t<li>Sport &amp; Recreation in the Public Services</li>\n\t<li>Expedition &amp; Land Navigation Skills</li>\n\t<li>Aspects of Law and the Public Services</li>\n</ul>\n\n<p><strong>Examples of enrichment trips include: </strong>Police riot training, outdoor and adventurous activities such as mountain climbing, boot camp, counter-terrorism experience and guest speakers from a range of local uniformed public services.</p>", "C_EMPLOYABILITY": "<p>This course is designed for entry to the uniformed services. Upon successful completion, depending on your goals and aims, you could progress with the following:</p>\n\n<ul>\n\t<li>Level 3 course</li>\n\t<li>Employment (subject to age restrictions)</li>\n\t<li>Apprenticeship</li>\n</ul>", "C_ELIGIBILITY": "<p>3 GCSEs at grades 9-3 in English and Maths and 1 other.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Learners are assessed throughout the course through a variety of activities, including:</p>\n\n<ul>\n\t<li>Assignment work</li>\n\t<li>Presentations and practical activities</li>\n\t<li>Trips&nbsp;</li>\n</ul>", "C_FEES": "<p>Please contact for details.</p>", "C_ADDITIONALFEES": "<p>Uniform and trips as required.</p>", "C_FUNDING": "", "C_CONTACT": "<p><a href=\"mailto:information@chelmsford.ac.uk\">careersadvicezone@chelmsford.ac.uk</a></p>", "C_METADESC": "<p>Prepare for a rewarding career in uniformed services with hands-on training, police riot sessions, fire and rescue days, and armed forces activities.</p>", "C_SEOTITLE": "Level 2 NCFE Course in Uniformed Services Essex - Chelmsford College", "C_SEOH1": "Level 2 NCFE Course in Uniformed Services", "C_SEOH2": "NCFE Level 2 Course in Policing, Fire Fighting & Armed Services", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If you are looking for a rewarding career in the uniformed services, then this Public Services course is for you. Enrolling in this course will unlock amazing opportunities for you linked with uniformed Public Services &ndash; from riot training with the Police to fire and rescue days and numerous activities linked with the armed forces including, outdoor and adventurous activities (OAA).</p>\n\n<p>We work towards promoting respectful, active citizens through additional duties and participation in all formal College events, so if you like representing people/organisations with pride, you will enjoy this.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:12:53", "C_CREATEDBY": "83439040", "C_UPDATED": "00:18:59", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Uniformed Services", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "494", "C_TITLE": "Enterprise and Entrepreneurship, Level 3", "C_SECTION": "5", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>BTEC Level 3 National Extended Diploma in Enterprise and Entrepreneurship</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "021", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The course requires students to set up and run their own business. Assessment will be through both practical and written tasks. An office area will be provided for students and business dress is to be worn.</p>\n\n<p><strong>Mandatory units</strong>:<br />\nThere are eight mandatory units, eight internally assessed and four externally assessed. Learners must complete and achieve at Pass grade or above for all units.</p>\n\n<p><br />\n<strong>Year 1 </strong></p>\n\n<ul>\n\t<li>Unit 1 Enterprise and Entrepreneurs</li>\n\t<li>Unit 2 Developing a Marketing Campaign</li>\n\t<li>Unit 3 Business and Personal Finance</li>\n\t<li>Unit 4 Launch and Run an Enterprise</li>\n\t<li>Unit 8 Entrepreneurship and Intrapreneurship in Practice</li>\n\t<li>Unit 9 Innovation and Enterprises</li>\n</ul>\n\n<p><strong>Units 2 and 3 are externally assessed in Year 1</strong></p>\n\n<p><br />\n<strong>Year 2</strong></p>\n\n<ul>\n\t<li>Unit 5 Survival and Growth</li>\n\t<li>Unit 6 Business Decision Making</li>\n\t<li>Unit 10 Recruitment and Selection Processes</li>\n\t<li>Unit 11 Marketing Communications (units are subject to change)</li>\n\t<li>Unit 12 Principles of Management</li>\n\t<li>Unit 13 Developing an Enterprise Strategy</li>\n</ul>\n\n<p><strong>Units 6 and 12 are externally assessed in Year 2</strong></p>\n\n<p>We also collaborate with stakeholders, including Chelmsford City Council, to increase opportunities for learners to develop their entrepreneurial skills, such as through a Youth Innovation Event.&nbsp;</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>University or HND course.</li>\n\t<li>Higher Apprenticeship/Degree Apprenticeship.</li>\n\t<li>Employment in a variety of different business careers.</li>\n\t<li>Successful students may go on to set up their own businesses, armed with the skills and experience gained on the course.</li>\n</ul>", "C_ELIGIBILITY": "<ul>\n\t<li>4 GCSEs grades 9-4 including&nbsp;English and Maths or successful achievement at a relevant level 2 vocational course.</li>\n\t<li>GCSE Business Studies or equivalent is desirable.</li>\n</ul>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>There are a range of assessment methods across the course - internal and external.</p>\n\n<p>Internal assessments are assessed using a variety of styles including writing up findings of research, using case studies to explore different situations, carrying out projects and demonstrating practical skills.</p>\n\n<p>External assessments are either examinations &ndash; all learners take the same assessment at the same time, normally with a written outcome.</p>\n\n<p>Set tasks &ndash; learners take the assessment during a defined window and demonstrate understanding through completion of a vocational task.</p>\n\n<p>The external units must be achieved at a Pass or above and learners are only permitted to re-sit the assessment once during their study programme.</p>", "C_FEES": "<p>Funded for 16-18 year olds</p>", "C_ADDITIONALFEES": "<p>Trip costs: to be advised<br />\nStationery: approximately &pound;20</p>\n\n<p>Learners will need to have &pound;100 start up capital</p>", "C_FUNDING": "", "C_CONTACT": "<p><a href=\"mailto:information@chelmsford.ac.uk\">c</a>areersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Business Enterprise & Entrepreneurship Course | Chelmsford College", "C_SEOH1": "Business Enterprise & Entrepreneurship Course", "C_SEOH2": "2026 Level 3 Enterprise & Entrepreneurship Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>The National Extended Diploma is a 2-year, full-time course ideal for anyone who wants to progress to higher education courses in business areas before entering employment. It can also support learners who want to progress directly to employment. The BTEC Level 3 National Extended Diploma in Enterprise and Entrepreneurship is equivalent to 3 A Levels.</p>\n\n<p>The aims of the course are to learn how to:</p>\n\n<ul>\n\t<li>Set up a supply chain.</li>\n\t<li>Learn how to communicate with customers.</li>\n\t<li>Opportunity to work closely with a business.</li>\n\t<li>Gain experience dealing with real business issues.</li>\n\t<li>Give learners the opportunity to plan, set up and run their own business through a structured programme of learning.</li>\n</ul>", "C_YEAR": "", "C_CREATED": "00:29:00", "C_CREATEDBY": "83439040", "C_UPDATED": "00:54:35", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Business", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "495", "C_TITLE": "T Level in Management and Administration (Specialism in Team Leadership and Management), Level 3", "C_SECTION": "5", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>T Level in Management and Administration</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>Learners will develop an understanding of a broad range of issues relevant to the sector, including:</p>\n\n<ul>\n\t<li>People:&nbsp;the importance and impact of people</li>\n\t<li>Finance:&nbsp;how revenue and expenditure is tracked and controlled</li>\n\t<li>Business Context:&nbsp;an overview of organisational cultures and values, different types of internal and external stakeholders, different forms of governance and the impact of organisations on society and the environment</li>\n\t<li>Project and Change Management:&nbsp;an understanding of the common change management theories and models and how to support and improve projects</li>\n\t<li>Business Behaviours:&nbsp;the importance of good communication and adapting social communication styles to professional standards&nbsp;according to purpose, medium and audience</li>\n\t<li>Quality and Compliance: the importance of maintaining and improving quality in all aspects of public and private sector organisations</li>\n\t<li>Policies:&nbsp;how organisations develop policies and why</li>\n</ul>\n\n<p>In addition to the core content, each learner will also specialise in team leadership and management in the second year of the programme.</p>\n\n<p>We also collaborate with stakeholders, including Chelmsford City Council, to increase opportunities for learners to develop their entrepreneurial skills, such as through a Youth Innovation Event.&nbsp;</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Within the workplace, you can progress onto roles such as a Supervisor, Team Leader or Project Manager.</li>\n\t<li>Within education you can progress onto degree options which include Business Management, Business Finance or Human Resources.</li>\n\t<li>Within Apprenticeships, You can progress onto a Level 3 in HR Support, Digital Marketer or Level 4 Associate Project Manager</li>\n\t<li>In 2022, 71% of learners who applied to university secured a place, while other T Level graduates moved into employment and higher apprenticeships.</li>\n</ul>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4 including<strong>&nbsp;</strong>English and Maths. GCSE Business Studies or equivalent is desirable.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<ul>\n\t<li>2 CORE Exams&nbsp;</li>\n\t<li>1 Employer Set Project&nbsp;</li>\n\t<li>1 Occupational Specialism Assessment&nbsp;</li>\n\t<li>45 Day/315 Hours in Industry Placement&nbsp;</li>\n</ul>", "C_FEES": "<p>There are no tuition fees to study a T Level if you start before you are 19.</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "T Level in Management & Administration | Chelmsford College", "C_SEOH1": "T Level in Management & Administration", "C_SEOH2": "2026 Level 3 in Business Management & Administration", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>T Levels are a 2-year qualification that you can do after GCSEs as an alternative to A Levels, other post-16 courses or an apprenticeship.</p>\n\n<p>The curriculum has been designed with leading businesses and employers to ensure you&#39;re equipped with the necessary skills and knowledge the industry is looking for.</p>\n\n<p>You&rsquo;ll spend 80% of your time in the classroom and 20% on a 45-day placement with an employer to give you the skills and knowledge companies look for.</p>\n\n<p>Your industry placement also gives you the chance to learn what a real career is like while you continue your studies.&nbsp;Like A Levels and BTECs, there are no tuition fees to study a T Level if you start before you are 19.</p>", "C_YEAR": "", "C_CREATED": "00:42:16", "C_CREATEDBY": "83439040", "C_UPDATED": "00:57:15", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Business", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "513", "C_TITLE": "VTCT Diploma in Hairdressing, Level 1", "C_SECTION": "12", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>VTCT Level 1 Diploma in Hairdressing</p>", "C_ADDITIONALQUALS": "<p>You will study Life Skills and also continue to study maths and English qualification if you have not already achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>\n\n<p>We collaborate with a range of stakeholders, to enhance our Hair &amp; Beauty courses based on industry feedback.</p>", "C_COURSECODE": "33189FT/QS", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This Level 1 Hairdressing course covers a variety of elements and topics to ensure that upon completion, learners are confident with their knowledge and skills to progress to their next steps. If enrolled on this programme, units you can expect to study include the following:</p>\n\n<ul>\n\t<li>Health and safety in the salon</li>\n\t<li>Introduction to the Hair and Beauty sector</li>\n\t<li>Shampoo and conditioning</li>\n\t<li>Colour hair using temporary colour</li>\n\t<li>Styling women&#39;s hair</li>\n\t<li>The art of dressing hair</li>\n\t<li>Salon reception duties</li>\n\t<li>Promote products and services to clients in the salon</li>\n\t<li>Plaiting and twisting hair</li>\n\t<li>Styling men&#39;s hair&nbsp;</li>\n\t<li>Creating an image</li>\n</ul>\n\n<p>Please note that learners are expected to work on each other initially to gain practical experience before they work on paying clients in The Princes Salons. Learners will also complete a minimum of 30 hours work related experience.&nbsp;</p>", "C_EMPLOYABILITY": "<p>Progression to further study could include the Level 2&nbsp;qualification in hairdressing&nbsp;or beauty therapy.&nbsp;</p>\n\n<p>&nbsp;</p>", "C_ELIGIBILITY": "<p>2 GCSEs grades 9-2 in English and Maths OR&nbsp; Functional Skills Level 1 in English and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>The course is assessed through online examinations and a range of practical assessments and assignments in a real working environment. You should be prepared to give and receive treatments.&nbsp;</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>Uniform - approximately &pound;43 &nbsp;</p>\n\n<p>Kit - approximately &pound;110</p>", "C_FUNDING": "", "C_CONTACT": "<p><a href=\"mailto:information@chelmsford.ac.uk\">careersadvicezone@chelmsford.ac.uk</a></p>", "C_METADESC": "Learn core hairdressing skills with this Level 1 course and gain the confidence to progress into Level 2 training.", "C_SEOTITLE": "Level 1 VTCT Diploma in Hairdressing Essex | Chelmsford College", "C_SEOH1": "Level 1 VTCT Diploma in Hairdressing", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If the hairdressing industry is one you&#39;d like to pursue but you&#39;re wondering how to enter the workforce, this course is for you. The primary outcome of the VTCT Level 1 Diploma in Hairdressing is to prepare you to progress to the next level of vocational learning. All the units within this qualification directly relate to the hairdressing industry. With further progression as well as the skills and qualification gained on this course, in time you will be able to work as a fully qualified Hairdresser either for a business or self-employed.</p>", "C_YEAR": "", "C_CREATED": "00:39:44", "C_CREATEDBY": "83439040", "C_UPDATED": "00:16:43", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Hair & Beauty", "levels": ["Foundation (Level One)"], "funding": ["16-18"]}, {"C_ID": "520", "C_TITLE": "VTCT Diploma in Beauty Therapy, Level 3", "C_SECTION": "12", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>VTCT Level 3 Extended Diploma in Beauty Therapy</p>", "C_ADDITIONALQUALS": "<p>You will study Life Skills and also continue to study a maths and English qualification if you have not achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>\n\n<p>We collaborate with a range of stakeholders, to enhance our Hair &amp; Beauty courses based on industry feedback. As a result, we have incorporated the <strong>Level 2 Skin Cancer Awareness</strong> qualification to better prepare learners for their careers.</p>", "C_COURSECODE": "32969FT", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>By offering a variety of units, this course has been designed to develop the skills you need to work in beauty therapy.</p>\n\n<p>There are a variety of units for you to study; modules include:</p>\n\n<ul>\n\t<li>Health and safety</li>\n\t<li>Skin and body analysis</li>\n\t<li>Swedish massage therapy</li>\n\t<li>Mechanical massage</li>\n\t<li>Face electrical treatments</li>\n\t<li>Body electrical science</li>\n\t<li>Anatomy and physiology for the face and body</li>\n\t<li>Electrical epilation</li>\n\t<li>Client care and consultation</li>\n\t<li>Microdermabrasion</li>\n</ul>\n\n<p>Please note that learners are expected to work on each other initially to gain practical experience before they work on paying clients in The Princes Salons. Learners will also complete a minimum of 30 hours work related experience.&nbsp;</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Progression to further study could include the Level 4 qualification in beauty therapy, salon management, holistic therapies or advanced beauty therapy.</li>\n\t<li>Career opportunities may include employment in commercial salons, spas, care homes, health farms and many more.</li>\n</ul>\n\n<p>Learners who achieve this qualification are eligible to become members of the British Association of Beauty Therapists and Cosmetology (BABTAC) or the Federation of Holistic Therapists (FHT).</p>", "C_ELIGIBILITY": "<p>GCSEs grades 9-3 in English and Maths and a full Level 2 qualification specific to your course.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>The course is assessed through an online examinations and a range of practical assessments and assignments in a real working environment. You should be prepared to give and receive treatments.&nbsp;</p>", "C_FEES": "<p>Please contact for details.</p>", "C_ADDITIONALFEES": "<p>Uniform - approximately &pound;47</p>\n\n<p>Kit - approximately &pound;77.10</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 3 VTCT Diploma in Beauty Therapy Treatments Essex", "C_SEOH1": "Level 3 VTCT Diploma in Beauty Therapy Treatments", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Throughout this qualification, learners will develop the knowledge, understanding, and skills to consult with clients, successfully promote retail products, and provide a range of beauty treatments, including Swedish massage, skin and body analysis, and electrical science, in order to make informed decisions for face and body electrical treatments. Learners will develop their communication and customer service skills, their awareness of environmental sustainability and their commercial skills, all of which are highly valued by employers.&nbsp;Within this qualification, you will develop a sound knowledge of health and safety, anatomy and physiology, client care, and communication, contributing to the effective running of a beauty therapy business. Overall, the purpose of this qualification is to develop your skills as a beauty therapist to enable you to provide beauty therapy treatments.</p>", "C_YEAR": "", "C_CREATED": "00:48:16", "C_CREATEDBY": "83439040", "C_UPDATED": "00:23:09", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Hair & Beauty", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "522", "C_TITLE": "Sport Programme, Level 2", "C_SECTION": "19", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "<p>Monday-Friday</p>", "C_QUALIFICATION": "<p>NCFE Level 2 Certificate in Sport (Sport, Exercise and Fitness), Level 2 Certificate in Supporting Learning in PE, School Sport and Physical Activity &amp; Level 2 Qualification in Community Sports Leadership&nbsp;</p>", "C_ADDITIONALQUALS": "<p>At Chelmsford College we are dedicated to helping all our learners achieve their ambitions and we acknowledge that in order to do well, some of our learners may need extra support in Maths and/or English.</p>\n\n<p>Please note that individual Level 2 literacy and numeracy may not be equivalent to a full GCSE qualification. We provide specialist teaching as a compulsory part of the study programme for all learners who have not achieved a grade 4 at GCSE in these subjects.</p>\n\n<p>We also work closely with stakeholders, including CIMSPA and Billericay Town Football Club, to improve our sport programmes based on their feedback, for example adding, CIMSPA-accredited CPD modules to align with industry needs.&nbsp;</p>", "C_COURSECODE": "32516PD", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course is comprised of the following qualifications:</p>\n\n<ul>\n\t<li>NCFE Level 2 Certificate in Sport (Sport, Exercise and Fitness)&nbsp;</li>\n\t<li>Level 2 Certificate in Supporting Learning in Physical Education, School Sport and Physical Activity&nbsp;</li>\n\t<li>Award in Community Sports Leadership&nbsp;</li>\n</ul>\n\n<p>These qualifications will cover topics such as:</p>\n\n<ul>\n\t<li>Anatomy &amp; Physiology</li>\n\t<li>Fitness, Coaching</li>\n\t<li>Health &amp; Safety</li>\n\t<li>Psychology and much more</li>\n</ul>\n\n<p>There is also a wide range of enrichment activities linked to the course in and around the local community. These provide you with further experience and opportunities to develop your sports leadership and employability skills.&nbsp;</p>", "C_EMPLOYABILITY": "<p><strong>Level Up: </strong>Progress to the NCFE Level 3 Sport and Physical Activity (Sport &amp; Exercise Science) course to deepen your knowledge and skills.&nbsp;</p>\n\n<p><strong>Get Paid While You Learn:</strong> Consider progressing to an apprenticeship to gain hands-on experience and earn while you train.&nbsp;</p>\n\n<p><strong>Kickstart Your Career: </strong>Open doors to potential employment in the sports sector, including:&nbsp;</p>\n\n<ul>\n\t<li>Coaching Positions: Supported by National Governing Body qualifications.&nbsp;</li>\n\t<li>Fitness Industry: From personal training to gym management.&nbsp;</li>\n\t<li>Sport and Recreation Centres: Work in vibrant environments where sports and leisure meet.&nbsp;</li>\n</ul>\n\n<p>Overall, by joining us, you can start to transform your love for sports into a rewarding career path!&nbsp;</p>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-3, including English Language and Maths at grades 9-2&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Learners are assessed throughout the course employing a variety of activities; this includes internally marked timed-assessments, assignment work, presentations and observation of practical activities.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p><strong>Non &ndash; Football Academy Sports Uniform </strong>&ndash; Approx. &pound;71.00  <a rel=\"external\" href=\"https://www.chelmsford.ac.uk/our-college/the-football-academy-kit.asp\" title=\"The Football Academy | Academy Kit\"><i class=\"fa fa-external-link\" aria-hidden=\"true\"></i></a></p>\n\n<p>Includes: 1x training jersey, 1x 1&frac14; zip top &amp; 1x shorts.</p>\n\n<p><strong>Football Academy Uniform</strong> - &pound;118.00 <a rel=\"external\" href=\"https://www.totalschoolsdirect.com/schools/chelmsford-college/chelmsford-college-sports-course-1\" title=\"The Football Academy | Academy Kit\"><i class=\"fa fa-external-link\" aria-hidden=\"true\"></i></a></p>\n\n<p>Includes: 2x training jerseys, 1x &frac14; zip top, 1x training pants &amp; 1x shorts.</p>\n\n<p><em>You are advised not to purchase the kit until your enrolment has been confirmed, as it cannot be returned.</em></p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 2 Sports Programme | Chelmsford College", "C_SEOH1": "Level 2 Sports Programme", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Kickstart Your Sports Career&nbsp;at Chelmsford College!&nbsp;If&nbsp;you are passionate about sports and dreaming of a future in the industry, our Level 2 Sports course is your gateway to a thrilling career in sports!</p>\n\n<p><strong>Here&rsquo;s what&rsquo;s in store for you:&nbsp;</strong></p>\n\n<ul>\n\t<li><strong>Hands-On Experience: </strong>Dive into the world of sports with practical and theoretical training that will make you industry ready.&nbsp;</li>\n\t<li><strong>Explore Human Performance: </strong>Discover the science behind peak athletic performance and how you can apply it to excel in your sport.&nbsp;</li>\n\t<li><strong>Fitness Industry Insights:</strong> Get insider knowledge about the fitness industry, from cutting-edge training techniques to the latest trends.&nbsp;</li>\n\t<li><strong>Sports in the UK: </strong>Learn how different organisations and agencies provide sports opportunities across the country.&nbsp;</li>\n\t<li><strong>Coaching Qualifications:</strong> Earn not one, but two industry-recognised coaching qualifications that will boost your CV and open doors to exciting job prospects.&nbsp;</li>\n\t<li><strong>Real-World Experience:</strong> Gain valuable work experience within the sports industry, making you a standout candidate for future employers.&nbsp;</li>\n</ul>\n\n<p>Join us and turn your passion for sports into a successful career. Enrol now and start your journey to becoming a sports industry pro!&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:10:23", "C_CREATEDBY": "83439040", "C_UPDATED": "00:14:43", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Sport", "levels": ["Intermediate (Level Two)"], "funding": ["16-18"]}, {"C_ID": "525", "C_TITLE": "National Extended Diploma Forensic and Criminal Investigation, Level 3", "C_SECTION": "3", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>National Extended Diploma Forensic and Criminal Investigation, Level 3&nbsp;</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This 2-year full-time course is equivalent to 3 A levels. If you are interested in forensic studies, criminology, and psychology, then this course will give you an insight into those areas. The course includes studying core biology, chemistry, physics and science investigation skills to underpin scientific knowledge before specialising in forensic analysis and investigation.</p>\n\n<p>Units may include forensic archaeology, anthropology, forensic genetics, forensic fire investigation, and traffic accident investigation. You will also study criminal psychology and criminology as core elements of the course.&nbsp;</p>", "C_EMPLOYABILITY": "<p>Skills in a scientific subject are transferable and highly sought after by employers. Upon successful completion, depending on your goals for what is next, you may progress to higher education, employment, including in digital forensic investigation or to a degree apprenticeship.</p>\n\n<p>Many learners progress to university, and this course is suitable for further studies in criminology, psychology, forensic investigation, forensic science, and policing studies. Learners may also apply for Border Force, Police and Armed Services.</p>", "C_ELIGIBILITY": "<p>4 GCSEs at&nbsp;grades 9-4 including Maths and Science and English Language at grade 9-3.</p>\n\n<p>&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "<p>Internal candidates should also have successful completion of current course to meet course entry requirements and meet College expectations regarding attendance and attitude</p>", "C_ASSESSMENT": "<p>Exams and coursework</p>", "C_FEES": "<p>&pound;30</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 3 Diploma in Forensic & Criminal Investigation Essex", "C_SEOH1": "Level 3 Diploma in Forensic & Criminal Investigation", "C_SEOH2": "National Extended Diploma Course in Forensic Science & Criminal Investigation", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This course is designed for individuals who are fascinated by the intricacies of forensic evidence. If you have a passion for understanding the scientific and psychological aspects of crime, such as how&nbsp;forensic evidence is gathered, processed, and analysed, as well as into the psychology of those who commit crimes, then this course could be for you. You will learn through activities based in our crime scene rooms, the laboratory, and the classroom, where a number of our activities are scenario-based. Overall, this Diploma in&nbsp;Forensic and Criminal Investigation will provide you with a good understanding of the industry from various angles.</p>", "C_YEAR": "", "C_CREATED": "00:34:05", "C_CREATEDBY": "83439040", "C_UPDATED": "00:15:11", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Science", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "527", "C_TITLE": "Access to Higher Education Diploma (Health Professions)", "C_SECTION": "2", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "9 months", "C_DAYS": "", "C_QUALIFICATION": "<p>Access to Higher Education Diploma (Health Professions)</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "October 2026, January 2027 and April 2027.", "C_STUDYOVERVIEW": "<p>Throughout the course, you will focus on developing essential study skills for university. These skills will be applied across various modules, which include topics such as the history of the NHS, the roles and responsibilities of health professionals, and body systems. All modules are assessed through coursework, which you will submit via the online learning platform.</p>", "C_EMPLOYABILITY": "<p>Upon completion of the Access to Higher Education Diploma (Health Professions), you will be equipped to make an informed decision about your career path and apply for a degree programme in a health profession. Opportunities exist to progress to a wide range of health-related degrees, such as nursing, occupational therapy, operating department practice, physiotherapy, radiotherapy, counselling or psychotherapy, dental nursing, and paramedic science.</p>\n\n<p>Please note that this list is not exhaustive, and entry requirements may vary between universities.</p>\n\n<p>If you wish to progress to midwifery or some nursing degrees, you will need a GCSE in Science (grade 4-9 or A-C). Some health-related degree courses may require 5 or 6 GCSEs (grade 4-9 or A-C), including English Language, Maths, and Science. You are advised to check university entry requirements carefully.</p>", "C_ELIGIBILITY": "<p>GCSE English Language and Maths at grades 4-9 or a pass on Functional Skills Level 2.</p>", "C_ELIGIBILITYSPECIFIC": "<p>Should be at least 19 years old by 31 August before starting the course.</p>\n\n<p>&nbsp;</p>", "C_ASSESSMENT": "<p>Independent study and coursework that includes essay writing and presentations.</p>", "C_FEES": "<p>Email studentfees@chelmsford.ac.uk for details</p>", "C_ADDITIONALFEES": "<p>UCAS application fee.</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Access to Higher Education Diploma (Health Professions)", "C_SEOH1": "Access to Higher Education Diploma (Health Professions)", "C_SEOH2": "Access to Higher Education Health Professionals", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Access to Higher Education (HE) courses are most suitable for 19+ learners who may like to undertake a university level course but did not gain the required qualifications during their school years. These courses are designed to offer you an alternative pathway to Higher Education, equipping you with the knowledge and qualifications needed to pursue your academic and career ambitions.&nbsp;</p>\n\n<p>If you have always been interested in a career as a health professional, you may already have some GCSEs but lack the appropriate Level 3 qualification. If you meet the entry requirements, this course could be the perfect starting point for you. The Access to Higher Education (Health Professions) course will provide you with a broad foundation to progress towards a degree and potentially a career in a health-related field.</p>\n\n<p>The course is delivered remotely, giving you the flexibility to learn at your own pace and from the comfort of your home. You will engage in self-directed learning through an online platform, with support from a progress tutor. To participate, you will need a computer and internet access to access course materials and complete assessments. Additionally, you will receive guidance on university applications and study skills to help you succeed and progress toward a degree in a health profession.</p>", "C_YEAR": "", "C_CREATED": "00:44:02", "C_CREATEDBY": "83439040", "C_UPDATED": "00:24:52", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Access to HE Diplomas (Studied Online)", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "535", "C_TITLE": "Diploma in Painting and Decorating, Level 1", "C_SECTION": "6", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 1 Diploma in Painting and Decorating</p>", "C_ADDITIONALQUALS": "<p>All Level 1 learners will also complete a Level 1 Award in Health and Safety in a Construction Environment to allow you to access a CSCS card which you will need to be able to go on site.</p>\n\n<p>We collaborate with stakeholders, including CITB and Quantum, to enhance our construction programmes based on their feedback. This has led to the addition of the CSCS/H&amp;S certificate, E3 Energy Efficiency and Sustainability Award, and Understanding Domestic Retrofit Award to align with industry needs.</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course is designed to help students gain a comprehensive understanding of painting and decorating by covering a range of essential topics and units. These units are essential to have a solid foundation in painting and decorating and will also equip you with the necessary skills that employers often look for when hiring individuals in this industry.</p>\n\n<p>When studying Level 1 Painting and Decorating, you can expect your units to include:</p>\n\n<ul>\n\t<li>Health and safety in construction</li>\n\t<li>The construction industry</li>\n\t<li>Environmental awareness and sustainability in construction</li>\n\t<li>The handling, moving&nbsp;and storing of&nbsp;resources</li>\n\t<li>Erect and dismantle access equipment or working platforms</li>\n\t<li>Personal wellbeing in construction</li>\n\t<li>Construction principles</li>\n\t<li>Further skills for painting and decorating</li>\n</ul>", "C_EMPLOYABILITY": "<p>Upon completion, if you&#39;re wish to progress with further study, this could be by enrolling on the following courses:</p>\n\n<ul>\n\t<li>Level 2 Diploma in Painting &amp; Decorating full time.</li>\n</ul>\n\n<p>Alternatively, if you&#39;re wishing to enter employment, career opportunities may include employment in the construction, painting, and decorating industry or&nbsp;an apprenticeship.</p>", "C_ELIGIBILITY": "<p>Commitment to working in the construction industry.&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Online exams and practical assessment&nbsp;</p>", "C_FEES": "<p>Free for under 19</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 1 Painting & Decorating Course Essex | Chelmsford College", "C_SEOH1": "Level 1 Painting & Decorating Course in Essex", "C_SEOH2": "Diploma in Painting & Decorating, Level 1", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Are you someone who wants to leave a lasting legacy and make a practical difference in people&#39;s lives? Do you have an eye for detail, a passion for learning, and an interest in the field of construction? If so, we recommend considering our Painting and Decorating Diploma.</p>\n\n<p>In this course, you will gain hands-on experience in all aspects of painting and decorating. You will learn the skills and techniques needed to make homes more inviting, create striking decorative effects, and improve existing buildings. With practical training and expert guidance, you will develop a keen eye for detail and a deep understanding of the tools and materials needed to do the job right.</p>\n\n<p>Upon completing our Painting and Decorating course, you will have the opportunity to start a rewarding career in the construction industry. You will be equipped with the knowledge and skills needed to work on a wide variety of projects. Whether you choose to work for a construction company or start your own business, the possibilities are endless.</p>", "C_YEAR": "", "C_CREATED": "00:47:37", "C_CREATEDBY": "83439040", "C_UPDATED": "00:33:24", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Construction", "levels": ["Foundation (Level One)"], "funding": ["16-18"]}, {"C_ID": "537", "C_TITLE": "Diploma in Plumbing Studies, Level 1", "C_SECTION": "6", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 1 Diploma in Plumbing Studies</p>", "C_ADDITIONALQUALS": "<p>All Level 1 learners will also complete a Level 1 Award in Health and Safety in a Construction Environment to allow you to access a CSCS card which you will need to be able to go on site.</p>\n\n<p>We collaborate with stakeholders, including CITB and Quantum, to enhance our construction programmes based on their feedback. (This has led to the addition of the CSCS/H&amp;S certificate, E3 Energy Efficiency and Sustainability Award, and Understanding Domestic Retrofit Award to align with industry needs).</p>\n\n<p>You will study Life Skills and continue to study a maths and English qualification if you have not achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course covers various units to ensure you&rsquo;re equipped with the necessary skills and knowledge to progress into the career you wish. Units of study you can expect to study:</p>\n\n<ul>\n\t<li>Installation, repair, and maintenance of plumbing systems</li>\n\t<li>Above-ground drainage</li>\n\t<li>Pipework (copper, plastic, low carbon steel)</li>\n\t<li>Plumbing science</li>\n</ul>\n\n<p>Core units will also include:</p>\n\n<ul>\n\t<li>Structure of the construction industry</li>\n\t<li>Fundamental safe working practices</li>\n\t<li>Environmental and sustainability measures in domestic dwellings</li>\n\t<li>Site preparation in the construction industry.</li>\n</ul>\n\n<p>&nbsp;</p>", "C_EMPLOYABILITY": "<p>Upon completion of this course, you could progress on to&nbsp;</p>\n\n<ul>\n\t<li>\n\t<p>Level 2 Plumbing&nbsp;full time&nbsp;</p>\n\t</li>\n</ul>\n\n<p>Career opportunities may include employment in the construction industry, or you could undertake an apprenticeship in plumbing.</p>", "C_ELIGIBILITY": "<p>2 GCSEs grades 9-3 in English and Maths</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Written exams and practical assessments&nbsp;</p>\n\n<p>&nbsp;</p>", "C_FEES": "<p>Free for under 19</p>", "C_ADDITIONALFEES": "<p>Work wear and protective equipment approximately &pound;35</p>\n\n<p>This includes:</p>\n\n<p>2 polo shirts</p>\n\n<p>1 hoodies</p>\n\n<p>Work boots - approximately &pound;24 or you can provide your own</p>\n\n<p>Optional - pair of trousers (costing and additional &pound;15)</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "Start your plumbing career with a beginner-friendly course, building essential skills through hands-on training in a high-demand construction trade.", "C_SEOTITLE": "Level 1 Plumbing Course Essex | Chelmsford College", "C_SEOH1": "Level 1 Plumbing Course in Essex", "C_SEOH2": "Diploma in Plumbing Studies, Level 1", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If you are passionate about pursuing a career in plumbing, this exciting qualification is an excellent option for you. This course is suitable for beginners as a first step into the construction industry. The plumbing industry is always in high demand and offers a wide range of opportunities for growth and advancement. &nbsp;During this programme, you will learn basic skills and advance your knowledge whilst being supervised as you undertake various practical and knowledge-based activities.</p>", "C_YEAR": "", "C_CREATED": "00:27:04", "C_CREATEDBY": "83439040", "C_UPDATED": "00:06:18", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Construction", "levels": ["Foundation (Level One)"], "funding": ["16-18"]}, {"C_ID": "540", "C_TITLE": "Diploma in Carpentry and Joinery, Level 1", "C_SECTION": "6", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 1 Diploma in Carpentry and Joinery</p>", "C_ADDITIONALQUALS": "<p>All Level 1 learners will also complete a Level 1 Award in Health and Safety in a Construction Environment to allow you to access a CSCS card which you will need to be able to work on site.</p>\n\n<p>We collaborate with stakeholders, including CITB and Quantum, to enhance our construction programmes based on their feedback. (This has led to the addition of the CSCS/H&amp;S certificate, E3 Energy Efficiency and Sustainability Award, and Understanding Domestic Retrofit Award to align with industry needs).</p>\n\n<p>You will study Life Skills and continue to study a maths and English qualification if you have not achieved a Grade 4 or Functional Skills Level 2.&nbsp;</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This Diploma in Carpentry and Joinery is designed to help you gain a comprehensive understanding of carpentry and joinery by covering a range of topics and units. These units will equip you with the necessary skills that employers look for when hiring individuals in this industry. The units studied are:&nbsp;</p>\n\n<ul>\n\t<li>Health and safety in construction&nbsp;</li>\n\t<li>The construction industry&nbsp;</li>\n\t<li>Environmental awareness and sustainability in construction&nbsp;</li>\n\t<li>Handle, move, and store resources&nbsp;</li>\n\t<li>Erect and dismantle access equipment or working platforms&nbsp;</li>\n\t<li>Personal well-being in construction&nbsp;</li>\n\t<li>Construction principles&nbsp;</li>\n\t<li>Skills for carpentry and joinery&nbsp;</li>\n\t<li>Further skills for carpentry and joinery&nbsp;</li>\n</ul>", "C_EMPLOYABILITY": "<p>Upon completion of this course, you could progress on to&nbsp;</p>\n\n<ul>\n\t<li>\n\t<p>Level 2 Diploma in Site Carpentry full time&nbsp;</p>\n\t</li>\n</ul>\n\n<p>Career opportunities may include employment in the construction industry, or you could undertake an apprenticeship in Site Carpentry.&nbsp;</p>", "C_ELIGIBILITY": "<ul>\n\t<li>All applicants will be assessed to ensure they are enrolled on the relevant level of course to meet their individual learning needs. Applicants may need to complete an English and Maths assessment.</li>\n\t<li>Commitment to working in the Construction Industry and if already a Chelmsford College learner, successful completion of current course and meeting College expectations regarding attendance and attitude.</li>\n</ul>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Online exams and practical assessments</p>", "C_FEES": "<p>Free for under 19</p>", "C_ADDITIONALFEES": "<p>Work wear and protective equipment approximately &pound;35</p>\n\n<p>This includes:</p>\n\n<p>2 polo shirts</p>\n\n<p>1 hoodies</p>\n\n<p>Work boots - approximately &pound;24 or you can provide your own</p>\n\n<p>Optional - pair of trousers (costing and additional &pound;15)</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "Looking to make a real difference? Our carpentry and joinery course is ideal for detail-driven learners with a passion for construction and hands-on skills.", "C_SEOTITLE": "Level 1 Carpentry & Joinery Course Essex | Chelmsford College", "C_SEOH1": "Level 1 Carpentry & Joinery Course in Essex", "C_SEOH2": "Diploma in Carpentry & Joinery, Level 1", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Are you someone who wants to leave a lasting legacy and make a practical difference in people&#39;s lives? Do you have an eye for detail, a passion for learning, and an interest in the field of construction? If so, we recommend considering our carpentry and joinery course.&nbsp;</p>\n\n<p>In this carpentry and joinery course, you will gain a solid foundation in the basics of carpentry, including the handling of materials, tools, and equipment. This is a 1-year introduction to the construction industry, featuring essential core units such as, health and safety, construction industry and construction principles and then specialist carpentry units to give you the skills to complete the job.</p>\n\n<p>If you have successfully gained GCSE 9-4 in English and maths, you can combine study of Level 1 carpentry and joinery with attending the Football Academy.</p>\n\n<p>Please note that this course is an introduction only, and progression is essential to gain semi-skilled and skilled status.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:33:44", "C_CREATEDBY": "83439040", "C_UPDATED": "00:04:55", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Construction", "levels": ["Foundation (Level One)"], "funding": ["16-18"]}, {"C_ID": "543", "C_TITLE": "Bespoke Provision (RARPA)", "C_SECTION": "50", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "<p>Chosen during initial assessment&nbsp;</p>", "C_QUALIFICATION": "<p>Bespoke Provision (RARPA)</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "Flexible", "C_STUDYOVERVIEW": "<p>Each curriculum is designed with the students&#39; pathways, preferences, and needs in mind and students are encouraged to take ownership of their planning to support engagement and motivation to learn. Progress and achievement are assessed through a Bespoke RARPA process that enables programmes and support to be flexible and student led.&nbsp;</p>\n\n<p>The course is designed to develop skills towards:</p>\n\n<ul>\n\t<li>Re-engaging with full-time education or transitioning into one of the colleges full-time study programmes.</li>\n\t<li>Work related experiences.</li>\n\t<li>Preparing for Independence, Good Health, and Community Participation</li>\n</ul>\n\n<p>Each student receives an individually created curriculum, support plans, care processes, and wellbeing support to help them engage in life as a student at Chelmsford College and as part of their local community safely and with increasing independence.</p>\n\n<p>We also listen to feedback from stakeholders, including Essex County Council, which helps us continually develop our programme.</p>", "C_EMPLOYABILITY": "<p>Upon completion of the programme, depending on the learner&#39;s and aims, they can advance to the following options:</p>\n\n<ul>\n\t<li>Extended Learning</li>\n\t<li>Kings Trust</li>\n\t<li>Supported Internships</li>\n\t<li>Vocational Courses</li>\n\t<li>Paid or unpaid supported employment and volunteer work</li>\n\t<li>Supported living and community participation</li>\n</ul>", "C_ELIGIBILITY": "<p>EHCP</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>RARPA</p>", "C_FEES": "", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Bespoke Provision Course for SEN (RARPA)", "C_SEOH1": "Bespoke Provision Course for SEN (RARPA)", "C_SEOH2": "RARPA Course for Young Adults with SEN", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Bespoke Provision provides individually planned curriculums and support for young adults with significant barriers to engaging in on-site, classroom-based, or full-time education. Each student receives one to one support for their education, care, and wellbeing needs to enable them to develop their ability to access education, core skills, preparation for next steps, and self-efficacy.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:01:35", "C_CREATEDBY": "83439040", "C_UPDATED": "00:02:39", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Bespoke Provision", "levels": ["RARPA (Recognising & Recording Progress & Achievement)"], "funding": []}, {"C_ID": "544", "C_TITLE": "Life Skills and Independence Pathway", "C_SECTION": "51", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "<p>4 Days</p>", "C_QUALIFICATION": "<p>RARPA</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The Life Skills and Independence pathway course is divided into 4 main areas:&nbsp;</p>\n\n<ul>\n\t<li><strong>Life skills and cooking:&nbsp;</strong>Learners will develop their cooking skills and other skills needed to live as independently as possible.&nbsp;</li>\n\t<li><strong>Social and community skills:</strong>&nbsp;Learners will discover how to access different facilities in the community and how to be safe when out in the community.&nbsp;</li>\n\t<li><strong>Healthy living:</strong>&nbsp;This unit focuses on staying healthy physically and mentally and gives learners the opportunity to try out a range of sports.&nbsp;&nbsp;</li>\n\t<li><strong>Employability skills:</strong>&nbsp;In this unit, learners will develop soft skills, such as teamwork and communication skills. They will also&nbsp;have the opportunity to participate in enterprise projects.&nbsp;</li>\n</ul>\n\n<p>English and maths skills are also an integral element of the course.&nbsp;</p>", "C_EMPLOYABILITY": "<p>Upon successful completion, with this Life Skills qualification and the significant enhancement of both life and independence skills, you could potentially progress onto the Employment and Vocational Pathway. Overall, this course is a great start to broaden your opportunities for personal and professional growth.</p>", "C_ELIGIBILITY": "<p>An ability to work in a small group setting.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>RARPA based course (Recognising and Rewarding Progress and Achievement).</p>\n\n<p>Progress against personal targets is tracked over the year.</p>", "C_FEES": "", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Life Skills for Special Educational Needs Students Essex", "C_SEOH1": "Life Skills & Independence Course for Special Educational Needs Students", "C_SEOH2": "Life Skills & Independence Course for Special Educational Needs Students", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>The Life Skills pathway is designed specifically for students with Special Educational Needs and/or Disabilities (SEND)&nbsp;working at pre-entry to entry level 2. Its purpose is to help them develop their life skills and independence, so they can successfully transition into adulthood. This comprehensive course content explores various aspects that are essential for advancing yourself both personally and professionally, such as social skills, communication techniques, and practical abilities for daily living and employment readiness.</p>", "C_YEAR": "", "C_CREATED": "00:12:06", "C_CREATEDBY": "83439040", "C_UPDATED": "00:05:48", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Foundation Provision", "levels": ["RARPA (Recognising & Recording Progress & Achievement)"], "funding": []}, {"C_ID": "553", "C_TITLE": "Gateway Diploma in Digital and IT Skills, Level 2", "C_SECTION": "15", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Gateway Qualifications Level 2 Diploma in Digital and IT Skills</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The qualification includes a mandatory unit and optional units that relate directly to the skills, knowledge and behaviours expected by employers. You will cover a wide range of topics and use different digital technologies, systems, and software. Overall, you will develop knowledge and understanding of the core areas of Digital and an introduction to the skills required in the Digital sector, acting as a good stepping stone into the industry or for further future study.</p>\n\n<p>We also collaborate with stakeholders, including Sharp, to continually develop our programmes by listening to feedback and ensuring learners gain real-world experience.&nbsp;</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Develop&nbsp;skills at a higher level by moving up the level of qualification from Level 2&nbsp;to Level 3</li>\n\t<li>Progress&nbsp;to employment where you can put&nbsp;your digital and IT knowledge and skills into practice.&nbsp;</li>\n</ul>", "C_ELIGIBILITY": "<p>3 GCSEs at grades 9-3 including English and Maths or a Level 1 vocational qualification</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>You will be assessed through assignment-based assessment.&nbsp;&nbsp;</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>&pound;50 trip</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 2 Diploma in IT & Digital Skills Essex - Chelmsford College", "C_SEOH1": "Level 2 Diploma in IT & Digital Skills", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This IT course is an excellent opportunity for individuals looking to extend and improve their digital skills. The course covers a diverse range of topics that can enhance your knowledge and proficiency in various digital fields. The practical skills and knowledge that you gain from this course can prepare you for a variety of job roles in the digital and creative industries, such as software and programming, network support, and digital design. Moreover, with the increasing demand for digital skills in various sectors ranging from finance, marketing, machining to manufacturing, this qualification can be beneficial for individuals seeking job opportunities in these sectors too. The course is tailored to provide a strong foundation in the digital skills required to excel in the modern workplace, and it is designed to help you keep pace with the rapidly changing digital landscape. Whether you are looking to upskill or reskill, this IT course can help you achieve your goals by providing you with the necessary knowledge and practical skills to succeed in the digital world. With expert guidance and support, you can unlock your potential and develop a strong foundation in digital skills that can help you kickstart your career.</p>", "C_YEAR": "", "C_CREATED": "00:21:07", "C_CREATEDBY": "83439040", "C_UPDATED": "00:08:33", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "ICT & Digital Skills", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "557", "C_TITLE": "T Level Technical Qualification in Media, Broadcast and Production, Level 3", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>Pearson T-Level Level 3 Technical Qualification in Media Broadcast and Production</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>You will develop a range of production skills using industry-standard equipment and software, including Adobe Premiere Pro, After Effects, Speed Grade, and Audition. You will explore and develop an understanding of a range of different production roles through pre-production, principle photography and post-production with the opportunity to explore your desired specialism further through set-specific projects. You will learn about different forms of story development through short films and web serials, as well as producing film and video content for a range of different client types. We will cover production techniques including directing actors, cinematic camera techniques, lighting, recording audio, industry-standard editing techniques and incorporating VFX.</p>\n\n<p>Using professional techniques through lectures, tutorials, seminars, and industry workshops, you will develop a portfolio of industry-standard work that will support you in the next step of your career or education journey.</p>\n\n<p>A series of guest speakers are included as part of the programme. You will also benefit from several field trips, our previous trips have included:</p>\n\n<ul>\n\t<li>Residential trip to Los Angeles/New York (not included in fees)</li>\n\t<li>Chelmsford Film Festival</li>\n\t<li>Harry Potter studio tour</li>\n\t<li>Location Tours</li>\n\t<li>Cinema screenings</li>\n</ul>", "C_EMPLOYABILITY": "<p>Students will develop transferrable skills, making them versatile and employable individuals. As the qualification has been designed to attract UCAS tariff points and is recognised by higher education providers as meeting university admission requirements, students completing this course usually go on to further study in degree-related programmes at university or in employment.&nbsp;&nbsp;</p>", "C_ELIGIBILITY": "<p>4 GCSEs at grades 9-4 including GCSE English and Maths</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>You will be assessed through an exam-based assessment. The core knowledge and understanding are evaluated through an examination, and core skills are assessed through a practical employer-set project.</p>", "C_FEES": "<p>First year: &pound;100</p>\n\n<p>Second year: &pound;90</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 3 T Level Course in Media, Broadcast and Production Essex | Chelmsford College", "C_SEOH1": "T Level Technical Qualification in Media, Broadcast and Production, Level 3", "C_SEOH2": "Full Time T Level Media, Broadcast and Production Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>Do you want to work in film and online streaming industries? With this course, you could become a director, screenwriter, cinematographer, editor or sound designer. You will explore the creative and technical aspects of film and online video production and gain the necessary skills to develop and produce short films and web-series episodes, music videos and corporate and promotional pieces for business clients.</p>\n\n<p>This course is structured to develop your professional industry skills, so we work closely with industry partners to ensure the course content remains relevant and you get the skills universities, apprenticeships, and employers need. You will develop further professional and transferable skills with opportunities to work with clients, plan and organise productions, pitch ideas to industry professionals and network within the independent film and online-streaming industry.</p>", "C_YEAR": "", "C_CREATED": "00:12:14", "C_CREATEDBY": "83439040", "C_UPDATED": "00:28:49", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "559", "C_TITLE": "UAL Level 2 Award and Diploma in Art and Design: Fashion and Textiles", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>UAL Level 2 Award and Diploma in Art and Design</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>We will introduce you to each of the different design areas listed above, and you will work on guided projects to help you improve your skills and develop your ideas. You will have the opportunity to specialise in your final project and your work will be exhibited in an exhibition. Working closely with professionals in the fashion and textiles industry, you will be kept up to date with current trends. You will be taught by both traditional and digital skills ensuring you know a range of techniques to complete a job.</p>\n\n<p>Visits to Galleries and Exhibitions in the past have included:</p>\n\n<ul>\n\t<li>Victoria and Albert Museum</li>\n\t<li>Kew Gardens</li>\n\t<li>Tate Modern Fashion &amp; Textiles Museum</li>\n\t<li>Specific locations for inspirational drawing &amp; photography</li>\n</ul>\n\n<p>At the end of this art and design course, you will have an individual portfolio of work.</p>\n\n<p>We also collaborate with stakeholders, including University of the Arts London, to continually develop our programmes by listening to feedback. From doing this, all art and design programmes are to be assessed via live briefs set by stakeholders ensuring learners meet and acknowledge industry requirements.&nbsp;</p>", "C_EMPLOYABILITY": "<p>The qualification will support students in developing a portfolio of work, enabling them to make applications to appropriate entry-level roles, training programmes, and&nbsp;apprenticeships.</p>\n\n<p>This qualification will support students to progress to a range of further education and vocational courses such as the UAL Level 3 Diploma and Extended in Fashion, Textiles and Interior Design.</p>", "C_ELIGIBILITY": "<p>2 GCSEs grade 9-3 OR successful achievement of a Level 1 vocational course</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Final Major Project&nbsp;</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>&pound;80 materials fee</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "UAL Level 2 Diploma in Art & Design Essex | Chelmsford College", "C_SEOH1": "UAL Diploma in Art and Design (Art, Design and Fashion), Level 2", "C_SEOH2": "Full Time Fashion & Textiles Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This fashion and textiles course is the perfect introduction to working within the creative design sector. You will explore a wide range of practical and research skills. By designing and making your own fabric, clothing, and accessories, you will develop and learn more about your own style. You will be taught by professional designers and use industry-standard equipment. The course will improve your confidence, and you will learn about progression opportunities in the design sector.</p>\n\n<p>If you see yourself working in any of these areas in the future, then this is the course for you:</p>\n\n<ul>\n\t<li>Fashion Design</li>\n\t<li>Textile Design</li>\n\t<li>Surface Pattern Design</li>\n</ul>\n\n<p>&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:30:30", "C_CREATEDBY": "83439040", "C_UPDATED": "00:12:04", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "562", "C_TITLE": "NCFE Diploma in Introduction to Health, Social Care and Children's and Young People's Settings, Level 1", "C_SECTION": "7", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "<p>3-4 days in college.</p>", "C_QUALIFICATION": "<p>Level 1 NCFE Diploma in Introduction to Health, Social Care and Children&#39;s and Young People&#39;s Settings&nbsp;</p>", "C_ADDITIONALQUALS": "<p>If you do not have GCSE Maths and/or English at grade 4 or above, you will be required to study English and Maths.&nbsp;&nbsp;</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>You will undertake a series of core units to develop a range of skills including, organisation, team working and research skills. You will be introduced to different disabilities, lifestyles, and support needs of clients, which will enable you to work effectively with a diverse range of people.</p>\n\n<p>You will learn and carry out activities to develop social and emotional needs, about healthy eating, and how to plan safe environments to create a nurturing and supportive environment.&nbsp;</p>", "C_EMPLOYABILITY": "<p>Completing a vocational course is a great foundation to help advance your career and prospects. Upon successful completion of this Level 1 vocational course, along with your relevant placement experience and achievement of English and Maths at grade 3, you will be considered for progression onto the Level 2 NCFE Certificate Working with Children in Early Years and Primary Settings (1 year) or onto another Level 2 course, such as Health and Social Care.</p>", "C_ELIGIBILITY": "<p>2 GCSEs at grades 9-2 in English and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Written assessment, role play, group activities and presentations.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>You may be required to purchase course textbooks, which are essential for the completion of your studies</p>\n\n<p>Enrichment activities throughout the course are to be paid for as necessary&nbsp;</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 1 NCFE Introduction Diploma to Child & Social Care | Chelmsford College", "C_SEOH1": "Level 1 NCFE Introduction Diploma to Child & Social Care in Essex", "C_SEOH2": "Level 1 NCFE Health & Social Care Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If you&#39;re not sure if you are interested in health and social care or childcare courses, we have the perfect course for you. This course will introduce you to the skills and qualities required to work in the fields of health and social care or with children. Throughout the course, you will have the opportunity to gain in-depth knowledge about these areas and develop essential skills that are highly valued and often required in the workforce.</p>\n\n<p>Additionally, you may have the opportunity to put your learning into practice by undertaking work experience in a professional setting. This will provide you with hands-on experience to add to your CV and allow you to explore different career options.?&nbsp;&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:54:03", "C_CREATEDBY": "83439040", "C_UPDATED": "00:03:11", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Childcare", "levels": ["Foundation (Level One)"], "funding": ["16-18"]}, {"C_ID": "565", "C_TITLE": "NCFE CACHE Certificate in Working with Children in Early Years and Primary Settings, Level 2", "C_SECTION": "7", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 2 NCFE CACHE Certificate in Working with Children in Early Years and Primary Settings&nbsp;</p>", "C_ADDITIONALQUALS": "<p>If you have GCSE Maths and English at grade 3, you will be required to study GCSE English and Maths.&nbsp;&nbsp;</p>\n\n<p>We also work closely with stakeholders, including Dovedale Nursery, to improve our early years programmes based on their feedback. As a result, we&#39;ve added paediatric first aid and infant mental health training as additional modules to align with industry needs.</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course is designed to provide you with a basic understanding of childcare and develop your skills in this area. The course consists of 6 units that will develop your theory and practical skills required for childcare. The work experience opportunity will also aid in supporting and developing your knowledge as you&rsquo;ll gain hands-on experience. This course is an excellent choice for anyone who wants to pursue a career in childcare or enhance their existing skills in this field.</p>", "C_EMPLOYABILITY": "<p>On successful completion of this Level 2&nbsp;course, including your placement experience and maths and English Language grades 4-9, you will be considered for progression onto the T Level in Education and Childcare (Early Years Educator pathway, Level 3) or onto another Level 3&nbsp;course.</p>\n\n<p>If you&rsquo;d prefer to go straight into employment, it may be possible to go into employment as a Level 2 practitioner. Additionally, another option (if you have the required English and maths grades) is to look into undertaking an apprenticeship.</p>", "C_ELIGIBILITY": "<p>Fully enhanced DBS check and 4 GCSEs at grades 9-3 including English Language and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "<p>Internal learners must have successful completion of current course to meet course entry requirements and meet College expectations regarding attendance and attitude.</p>", "C_ASSESSMENT": "<p>All units are&nbsp;assessed through coursework.</p>\n\n<p>A minimum of 120 hours placement with professional reflective record.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<ul>\n\t<li>Uniform of Polo shirts&nbsp; (approximately &pound;9 each) and Sweatshirt&nbsp; (approximately &pound;12 each) to be purchased.&nbsp;&nbsp;</li>\n\t<li>Uniform is to be worn in college and at placement&nbsp;</li>\n\t<li>DBS approximately &pound;50&nbsp;</li>\n\t<li>You may be required to purchase course text books which are essential for the completion of your studies.&nbsp;&nbsp;</li>\n\t<li>Enrichment activities throughout the course to be paid for as necessary&nbsp;</li>\n</ul>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Level 2 NCFE Certificate in Early Years & Primary School Settings | Chelmsford College", "C_SEOH1": "Level 2 NCFE Certificate Working With Children in Early Years and Primary Settings", "C_SEOH2": "Level 2 NCFE Course in Early Years & Primary School", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If you&#39;re interested in studying early childhood education courses, this is the course for you. Studying this course will allow you to develop your skills, qualities, and confidence to work in the childcare sector (either early years or primary), or it will help you prepare for your next steps in education if you want to progress to a higher level. The course consists of a range of varied units designed to develop your theoretical and practical skills. Throughout the year, there will be 2 days of work experience per week in a variety of settings which will all help to support your overall understanding and boost your CV.</p>\n\n<p>Although having experience of working with or being around children is not essential, it would be highly advantageous for your study programme.</p>", "C_YEAR": "", "C_CREATED": "00:42:17", "C_CREATEDBY": "83439040", "C_UPDATED": "00:05:11", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Childcare", "levels": ["Intermediate (Level Two)"], "funding": ["16-18"]}, {"C_ID": "595", "C_TITLE": "Diploma Electrical Installations, Level 2", "C_SECTION": "8", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>EAL Level 2 Diploma in Electrical Installations</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course is comprised of practical and theoretical elements to ensure upon completion, you have the necessary skills, understanding, and knowledge to progress to where you wish.</p>\n\n<ul>\n\t<li><strong>30%</strong> of the course involves <strong>practical</strong> tasks in the workshop, building hand skills, basic requirements, and good practices for electrical installations.</li>\n\t<li><strong>70%</strong> of the course is <strong>theory </strong>on the safe working and health and safety, electrical installation practices, and knowledge of tools and equipment.</li>\n</ul>\n\n<p>If you additionally have a passion for football, the course also offers the opportunity to take part in our Football Academy in conjunction with Billericay Town FC.</p>", "C_EMPLOYABILITY": "<p>Following successful completion of this course, progression to further study could include:&nbsp;</p>\n\n<ul>\n\t<li>Level 3 Apprenticeship in Electrotechnical Systems and Equipment.</li>\n</ul>", "C_ELIGIBILITY": "<p>GCSEs grades 9-4 in English and Maths&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<ul>\n\t<li>Written exam</li>\n\t<li>Online exam</li>\n\t<li>Practical assessment</li>\n</ul>", "C_FEES": "", "C_ADDITIONALFEES": "<p>Any learner enrolling to Level 2 Electrical will be required to purchase a Level 2 textbook and the latest version of the On-Site Guide BS7671:2022</p>\n\n<p>For direct entry you will need to purchase the Onsite Guide plus a text book.</p>\n\n<p>Work wear and protective equipment approximately &pound;35</p>\n\n<p>This includes:</p>\n\n<p>2 polo shirts</p>\n\n<p>1 hoodies</p>\n\n<p>Work boots - approximately &pound;24 or you can provide your own (steel toe capped boots not trainers)</p>\n\n<p>Optional - pair of trousers (costing and additional &pound;15)</p>\n\n<p>Optional purchase of working gloves, glasses and ear protection.&nbsp;</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Full Time Level 2 Diploma in Electrical Installation Essex | Chelmsford College", "C_SEOH1": "Full Time Level 2 Diploma in Electrical Installation in Essex", "C_SEOH2": "Level 2 Electrician Course", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This qualification allows you to acquire the knowledge and craft skills of electrical installation. It does not require occupational evidence from the workplace, so is suitable if you do not currently work within the electrical industry but who may wish to do so. The qualification will give you an opportunity to practice and be assessed in a secure environment on the installation of wiring systems together with the relevant theory of electrical installation. You will become familiar with the IET On-Site Guide and gain knowledge of electrical science and principles, to gain understanding of electrical circuits. This qualification does not make you an electrician but allows progression to further study.</p>", "C_YEAR": "", "C_CREATED": "00:39:15", "C_CREATEDBY": "83439040", "C_UPDATED": "00:11:30", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Electrical Installation", "levels": ["Intermediate (Level Two)"], "funding": ["16-18"]}, {"C_ID": "597", "C_TITLE": "Diploma in Engineering Technologies, Level 1", "C_SECTION": "9", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>EAL Level 1 Diploma in Engineering Technologies</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The course is made up of one externally examined unit, which is mandatory and 8 additional units as follows:</p>\n\n<ul>\n\t<li>Introduction to working in engineering (external exam).</li>\n\t<li>Introduction to machining engineering materials (unit 2).</li>\n\t<li>Introduction to cutting, forming and assembling engineering materials (unit3).</li>\n\t<li>Introduction to electronics (unit 5).</li>\n\t<li>Introduction to electrical installation (unit 6).</li>\n\t<li>Introduction to cycle maintenance (unit 11).</li>\n\t<li>Introduction to basic maths and science used in engineering (unit 13).</li>\n\t<li>Introduction to CAD - computer aided drawing (unit 15).</li>\n\t<li>Project (unit 17).</li>\n</ul>", "C_EMPLOYABILITY": "<p>Progression to further study could include the level 2 VRQ Diploma in Engineering Technologies or an apprenticeship such as the level 2 Engineering Operative standard.</p>\n\n<p>Career opportunities may include operative, trainee or technician positions in the engineering and manufacturing sectors.</p>", "C_ELIGIBILITY": "<p>2 GCSEs grades 9-2 in English and Maths&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<ul>\n\t<li>External exam (online)</li>\n\t<li>Internal assessments consisting of practical evidence and knowledge tests for each unit. Learners are required to pass each knowledge assessment to complete the unit.</li>\n\t<li>Practical evidence for each unit from a mixture of made items, printed images, report writing and witness checklists.</li>\n</ul>", "C_FEES": "<p>Please contact for details&nbsp;</p>", "C_ADDITIONALFEES": "<p>Approx. &pound;50:</p>\n\n<ul>\n\t<li>Steel toe cap safety boots.</li>\n\t<li>Overalls or dust coat (blue).</li>\n\t<li>Scientific calculator.</li>\n\t<li>Maths set.</li>\n\t<li>Stationery.</li>\n\t<li>Padlock for locker.</li>\n</ul>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "Gain a solid introduction to engineering, covering core principles and industry roles, ideal for anyone considering a future career in engineering.", "C_SEOTITLE": "Level 1 Engineering Technologies Course Essex | Chelmsford College", "C_SEOH1": "Level 1 Diploma in Engineering Technologies", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This course is designed to offer a comprehensive understanding of the engineering industry to learners who are interested in gaining a fundamental knowledge of the subject. The course material covers a wide range of topics, including the basic principles of engineering and the role of engineers in different industries. It is a great opportunity for individuals who are considering pursuing a career in engineering.</p>", "C_YEAR": "", "C_CREATED": "00:56:02", "C_CREATEDBY": "83439040", "C_UPDATED": "00:50:23", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Engineering", "levels": ["Foundation (Level One)"], "funding": []}, {"C_ID": "699", "C_TITLE": "T Level in Marketing, Level 3", "C_SECTION": "5", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>T Level in Marketing</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>During the 2-year programme, students will learn the core knowledge and skills that are needed for entry to a range of marketing occupations.&nbsp;</p>\n\n<p>Students will develop an understanding of a broad range of issues relevant to the sector, including:&nbsp;</p>\n\n<ul>\n\t<li>The purpose of marketing, how it adds value to an organisation including leadership, culture and vision and the impact of no marketing activity&nbsp;</li>\n\t<li>Role of marketing including marketing as a management process, its importance, market type and reach&nbsp;</li>\n\t<li>The key differences between consumers and customers and the different ways to influence them&nbsp;</li>\n\t<li>Routes to market including the role of suppliers and procurement: business to business (B2B), business to consumer (B2C) and other channels, and how this influences marketing activity&nbsp;</li>\n\t<li>Customer personas and how they are used to determine marketing campaigns&nbsp; including purpose and typical types, e.g. competitive, spontaneous,analytical, and methodical&nbsp;</li>\n\t<li>Different types of customers and consumers and what influences their behaviours&nbsp;</li>\n\t<li>Organisational purpose and business aims including for-profit and not for profit marketing objectives&nbsp;</li>\n\t<li>The marketing and extended promotional mix (advertising, personal selling,sales promotion, public relations and direct marketing) including the differences between the channels and the benefits of a coordinated marketing mix&nbsp;&nbsp;</li>\n</ul>\n\n<p>In addition to the core content, each student will also complete at least one module of occupation-specific content. The specialisms available in the Marketing T Level are:&nbsp;</p>\n\n<ul>\n\t<li>\n\t<p>Marketing Assistant (Multi-Channel)&nbsp;</p>\n\t</li>\n</ul>\n\n<p>We also collaborate with stakeholders, including Chelmsford City Council, to increase opportunities for learners to develop their entrepreneurial skills, such as through a Youth Innovation Event.&nbsp;</p>", "C_EMPLOYABILITY": "<p>Within the workplace, you can progress onto roles that might include:&nbsp;</p>\n\n<ul>\n\t<li>Advertising and Media Executive&nbsp;</li>\n\t<li>Digital Marketer&nbsp;</li>\n\t<li>E-commerce Manager&nbsp;</li>\n\t<li>Events Manager&nbsp;</li>\n\t<li>Fundraiser&nbsp;</li>\n\t<li>Marketing Assistant&nbsp;</li>\n\t<li>Marketing Officer</li>\n\t<li>Marketing Manager&nbsp;</li>\n\t<li>Marketing Researcher&nbsp;</li>\n\t<li>Public Relations Manager&nbsp;</li>\n</ul>\n\n<p>Within education you can progress onto degree options which include Business Marketing, Business Finance or other similar pathways.&nbsp;</p>\n\n<p>Within Apprenticeships, you can progress onto Digital Marketer or other similar pathways.&nbsp;</p>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4 including<strong>&nbsp;</strong>English and Maths. GCSE Business Studies or equivalent is desirable.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<ul>\n\t<li>2 CORE Exams&nbsp;</li>\n\t<li>1 Employer Set Project&nbsp;</li>\n\t<li>1 Occupational Specialism Assessment&nbsp;</li>\n\t<li>45 Day/315 Hours in Industry Placement&nbsp;</li>\n</ul>", "C_FEES": "", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "Advanced T-Level Course in Marketing Essex - Chelmsford College", "C_SEOH1": "Advanced T-Level Course in Marketing", "C_SEOH2": "Level 3 Course in Marketing", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>T Levels are a 2-year qualification that you can do after GCSEs as an alternative to A Levels, other post-16 courses or an apprenticeship.</p>\n\n<p>The curriculum has been designed with leading businesses and employers to ensure you&#39;re equipped with the necessary skills and knowledge the industry is looking for.</p>\n\n<p>You&rsquo;ll spend 80% of your time in the classroom and 20% on a 45-day placement with an employer to give you the skills and knowledge companies look for.</p>\n\n<p>Your industry placement also gives you the chance to learn what a real career is like while you continue your studies.&nbsp;Like A Levels and BTECs, there are no tuition fees to study a T Level if you start before you are 19.</p>", "C_YEAR": "", "C_CREATED": "00:36:00", "C_CREATEDBY": "83439040", "C_UPDATED": "00:57:44", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Business", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "721", "C_TITLE": "T Level in Legal Services, Level 3", "C_SECTION": "5", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "<p>4 days in college and 1 day at the workplace&nbsp;</p>", "C_QUALIFICATION": "<p>T Level in Legal Services</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>There are three Performance Outcomes (PO) to ensure this Legal Services T Level is well rounded and comprehensive:</p>\n\n<ul>\n\t<li><strong>PO1:</strong> Assist with the inception, progression and completion of legal services in Business, Finance and Employment</li>\n\t<li><strong>PO2:</strong>&nbsp;Carry out legal and factual research and present findings both orally and in writing in Business, Finance and Employment</li>\n\t<li><strong>PO3:</strong> Draft legal documents and standard legal communications in Business, Finance and Employment, for review by a supervisor&nbsp;</li>\n</ul>\n\n<p>Across the 2 years you will study a variety of topics to ensure that upon successful completion, you are ready to secure employment or progress your studies.</p>\n\n<p>In year 1 you will cover units such as:</p>\n\n<ul>\n\t<li>The business environment&nbsp;</li>\n\t<li>Regulation</li>\n\t<li>Careers within the legal professions</li>\n\t<li>Security and risk</li>\n</ul>\n\n<p>While in year 2, you will specialise in Legal Services Assistant in Business, Finance and Employment.&nbsp;</p>\n\n<p>We also collaborate with stakeholders, including Chelmsford City Council, to increase opportunities for learners to develop their entrepreneurial skills, such as through a Youth Innovation Event.&nbsp;</p>", "C_EMPLOYABILITY": "<p>The qualification is intended to help you progress into highly skilled employment in the Legal Services sector, with a focus on business services or crime and criminal justice.</p>\n\n<p>Job roles open to you once you complete your T Level could include:</p>\n\n<ul>\n\t<li>Paralegal</li>\n\t<li>Legal Secretary Usher.</li>\n</ul>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4 including<strong>&nbsp;</strong>English and Maths. GCSE Business Studies or equivalent is desirable.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<ul>\n\t<li>2 CORE Exams&nbsp;</li>\n\t<li>1 Employer Set Project&nbsp;</li>\n\t<li>1 Occupational Specialism Assessment&nbsp;</li>\n\t<li>45 Day/315 Hours in Industry Placement</li>\n</ul>", "C_FEES": "<p>There are no tuition fees to study a T Level if you start before you are 19</p>", "C_ADDITIONALFEES": "<ul>\n\t<li>&pound;25 enrichment course costs</li>\n\t<li>&pound;30 (approximate) for course textbook which is a mandatory purchase</li>\n</ul>", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "Advanced T Level Course in Legal Services Essex - Chelmsford College", "C_SEOH1": "Advanced T Level Course in Legal Services", "C_SEOH2": "Level 3 Course in Legal Services", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>T Levels are a 2-year qualification that you can do after GCSEs as an alternative to A Levels, other post-16 courses or an apprenticeship.</p>\n\n<p>The curriculum has been designed with leading businesses and employers to ensure you&#39;re equipped with the necessary skills and knowledge the industry is looking for.</p>\n\n<p>You&rsquo;ll spend 80% of your time in the classroom and 20% on a 45-day placement with an employer to give you the skills and knowledge companies look for.</p>\n\n<p>Your industry placement also gives you the chance to learn what a real career is like while you continue your studies.&nbsp;Like A Levels and BTECs, there are no tuition fees to study a T Level if you start before you are 19</p>", "C_YEAR": "", "C_CREATED": "00:44:17", "C_CREATEDBY": "83439040", "C_UPDATED": "00:56:45", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Business", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "724", "C_TITLE": "IN2 FE NCFE Certificate - Entry to the Uniformed Services, Level 1", "C_SECTION": "17", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "35 weeks", "C_DAYS": "<p>5 days</p>", "C_QUALIFICATION": "", "C_ADDITIONALQUALS": "<p>Maths, English and Life Skills.&nbsp;</p>\n\n<p>We collaborate with stakeholders, including Essex Air Ambulance and Essex Police, to enhance our Public Services courses based on industry feedback.&nbsp;</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This course includes 30 hours of work-related experience and covers various topics to ensure that upon successful completion, you are equipped with the essential skills and knowledge to progress to your next steps.&nbsp;</p>\n\n<p><strong>Units covered throughout this uniformed services course include:</strong></p>\n\n<ul>\n\t<li>Investigate Employment Opportunities in the Uniformed Services&nbsp;</li>\n\t<li>Wellbeing and Physical Fitness for the Uniformed Services&nbsp;</li>\n\t<li>Team Working Skills in the Uniformed Services&nbsp;</li>\n\t<li>Developing Self-Discipline for the Uniformed Services&nbsp;</li>\n\t<li>Health and Safety in the Uniformed Services&nbsp;</li>\n\t<li>Carry Out Map Reading and Navigation&nbsp;</li>\n\t<li>Participate in Competitive Sport&nbsp;</li>\n\t<li>Participate in an Adventurous Activity&nbsp;</li>\n\t<li>Explore Volunteering and Volunteering Opportunities&nbsp;</li>\n</ul>", "C_EMPLOYABILITY": "<p><strong>Progression and Employment Opportunities:</strong></p>\n\n<p>Level 2 Uniformed Public Services or another Level 2 course.</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>", "C_ELIGIBILITY": "<p>GCSE grades 9-2 in English and Maths OR &nbsp;Functional Skills Level 1 in English and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>The course is assessed through a range of practical assessments and assignments. &nbsp;</p>", "C_FEES": "<p>Please contact for details.&nbsp;</p>", "C_ADDITIONALFEES": "<p>Uniform and trips as required.</p>", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "<p>Explore a career in public services with our uniformed services course, offering insight into roles across the police, fire service, ambulance service and military.</p>", "C_SEOTITLE": "NCFE Certificate in Uniformed Services | Chelmsford College", "C_SEOH1": "IN2 FE (NCFE Level 1 Certificate in Uniformed Services)", "C_SEOH2": "Level 1 Vocational Course in Uniformed Services", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>If you are considering a career in the public services sector, this uniformed services course could be the ideal stepping stone for you. Designed specifically for individuals interested in exploring the wide range of opportunities available within public services, this course will give you an in-depth understanding of what it takes to join various uniformed services, such as the police, fire service, ambulance service, and military. Throughout the course, you will engage with a combination of public service and employability units that are structured to help you develop essential transferable skills. These skills are crucial not only for a successful career in public service but also for everyday life. You will learn effective communication, teamwork and problem-solving skills&mdash;capabilities that are highly valued across all sectors. Moreover, the curriculum is tailored to provide you with the knowledge and understanding of the key requirements, responsibilities, and challenges faced by professionals in this field. By the end of the course, you will have a clearer vision of your career path and the skills necessary to thrive in a public service role, making a positive impact in your community and beyond.</p>", "C_YEAR": "", "C_CREATED": "00:23:27", "C_CREATEDBY": "83439040", "C_UPDATED": "00:18:01", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Uniformed Services", "levels": ["Foundation (Level One)"], "funding": []}, {"C_ID": "734", "C_TITLE": "BTEC National Extended Diploma in IT, Level 3", "C_SECTION": "15", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "<p>4 days &ndash; Monday, Tuesday, Wednesday, Friday if re-sitting GCSE Maths or English (two/three days for no resits)</p>", "C_QUALIFICATION": "<p>BTEC Level 3 National Extended Diploma in IT</p>", "C_ADDITIONALQUALS": "<p>GCSE Maths or English if a learner has not already achieved a Grade 4 or above in their school exams.</p>", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The BTEC Level 3 in Information Technology (IT) is a specialist, work-related qualification designed for post-16 learners who are interested in a practical and theoretical approach to IT.</p>\n\n<p>If you&#39;re contemplating studying this IT course, here&#39;s some key facts about this course to help you decide:</p>\n\n<p><strong>What Will You Study?</strong></p>\n\n<ul>\n\t<li>The course covers a wide range of IT topics, including:</li>\n\t<li>Information Technology Systems</li>\n\t<li>Creating Systems to Manage Information</li>\n\t<li>Using Social Media in Business</li>\n\t<li>Programming</li>\n\t<li>Data Modelling</li>\n\t<li>Website and Mobile App Development</li>\n\t<li>Cyber Security and Incident Management</li>\n</ul>\n\n<p>You will complete both practical assignments and theory-based work, often linked to real-world business scenarios to equip you with the necessary skills and knowledge needed when finding a job within IT.</p>", "C_EMPLOYABILITY": "<p>The BTEC Level 3 IT is equivalent to up to three A Levels, making it a strong route to university, higher apprenticeships, or direct employment.</p>\n\n<p>Graduates can pursue careers in:</p>\n\n<ul>\n\t<li>Software development</li>\n\t<li>Web and games design</li>\n\t<li>IT support and technical roles</li>\n\t<li>Cyber security</li>\n\t<li>Business analysis</li>\n</ul>\n\n<p>The course is also a stepping stone to further study in computing, IT, or related fields at university.</p>", "C_ELIGIBILITY": "<p>4 GCSEs grades 9-4&nbsp;</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Mixture of internal/externally assessed units and external assessments.&nbsp;</p>", "C_FEES": "<p>&pound;100 for trip fees.</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "", "C_SEOH1": "", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This Level 3 BTEC in IT provides students with a solid foundation for understanding and applying this subject in their future working lives. IT enables students to make the leap from passive consumers to active producers of quality digital content.</p>\n\n<p>The course is designed with input from employers and universities to ensure you gain up-to-date, relevant skills essential to thrive within the industry.&nbsp;</p>\n\n<p>You&rsquo;ll benefit from supportive teaching, personal tutoring, and resources to help you succeed and ensure you unlock your full potential.&nbsp;</p>", "C_YEAR": "", "C_CREATED": "00:30:39", "C_CREATEDBY": "83439040", "C_UPDATED": "00:09:18", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "ICT & Digital Skills", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "743", "C_TITLE": "UAL Level 2 Award and Diploma in Performing and Production Arts", "C_SECTION": "55", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 2 Award and Diploma in Performing and Production Arts</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>Learners will explore performance, set design, props, costume and technical production and build on their creative skills through real-world projects, live briefs and partnerships with local theatres and arts organisations.&nbsp;Learners will take on exciting assignments&nbsp;developing performance, design, and storytelling skills across key styles and themes.</p>\n\n<p>The skills gained are highly transferable, preparing learners for a wide range of UAL Level 3 courses from Performing and Production Arts to Art and Design or Creative Media. with a strong foundation in storytelling, collaboration, design and creative thinking.</p>", "C_EMPLOYABILITY": "<p>Upon successful completion, learners will be able to progress to Level 3 in a theatre or arts specialism that fits their passion.</p>", "C_ELIGIBILITY": "<p>A minimum of 2 GCSEs at grades 9-3 or above OR successful achievement at a Level 1 vocational course along with Drama or Dance (compulsory) and Functional Skills English and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "", "C_FEES": "<p>&pound;175 materials fee. This&nbsp;covers three theatre trips which&nbsp;are carefully chosen to enhance your knowledge of production across diverse styles, from naturalist and non-naturalist theatre to Theatre in Education, directly inking to your course units.</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "Level 2 Diploma in Performing & Production Arts in Essex", "C_SEOH1": "UAL Level 2 Award & Diploma in Performing & Production Arts (Subject to Award Approval)", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This UAL Level 2 Performing and Production Arts course introduces learners to a wide range of creative techniques through experimental and personal approaches. Focusing on visual storytelling, emotion and identity, learners explore materials, processes and ideas across 2D, 3D and time-based media. Through practical projects and reflective practice, learners build the confidence, skills and contextual understanding needed to progress to Level 3 study or entry-level creative roles. This dynamic course gives learners a hands on introduction to the world of theatre production, from acting and performance to set, props and costumes. Designed to mirror the full theatre pipeline, it helps learners discover their strengths across creative and technical roles.</p>", "C_YEAR": "", "C_CREATED": "00:16:05", "C_CREATEDBY": "83439040", "C_UPDATED": "00:04:39", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Performing Arts", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "751", "C_TITLE": "UAL Level 3 Diploma and Extended Diploma in Performing and Production Arts", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "", "C_QUALIFICATION": "<p>Level 3 Diploma and Extended Diploma in Performing and Production Arts</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>Learners will explore a wide range of performance disciplines, including acting, movement, voice and devised theatre. Through practical workshops, rehearsals and real-world performance projects, they will build confidence, creativity and professional skills essential for progression in the performing arts industry.</p>\n\n<p>Learners will take on exciting assignments, developing performance, design and storytelling skills across multiple styles and themes.</p>", "C_EMPLOYABILITY": "<p>The skills gained are highly transferable, providing learners with a strong foundation for progression to higher education, further education, employment and other training opportunities.&nbsp;</p>", "C_ELIGIBILITY": "<p>A minimum of 4 GCSEs at grades 9-3 or above OR successful achievement at a Level 2 vocational course along with Drama or Dance (compulsory) and Functional Skills English and Maths.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Coursework and performance/production in a show.</p>", "C_FEES": "<p>&pound;175 materials fee.</p>\n\n<p>This&nbsp;covers external workshops, guest speakers, theatre trips and resources which&nbsp;are carefully chosen to enhance your knowledge of production across diverse styles, from naturalist and non-naturalist theatre to Theatre in Education, directly linking to your course units.</p>", "C_ADDITIONALFEES": "", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "Level 3 Extended Diploma in Performing & Production Arts", "C_SEOH1": "UAL Level 3 Extended Diploma in Performing & Production Arts (Subject to Award Approval)", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This Level 3 Diploma and Extended Diploma in Performing and Production Arts is designed to provide learners with the knowledge, skills and understanding necessary to access and progress to degree level study or employment in the performing arts.</p>\n\n<p>It provides an opportunity for those who have an interest in the performing arts to explore, develop and test their creativity within a qualification structure which is stimulating, demanding and provides a supportive transition from general to more specialised study.</p>\n\n<p>By the end of this course, learners will have a critical and contextual awareness of different perspectives and approaches within performing and production arts. Through exploring character design, performance skills, production techniques, scriptwriting and costume construction, you will gain a well-rounded skillset for higher education or entry into the creative industries.</p>\n\n<p>This course gives learners a hands-on introduction to the world of theatre production, from acting and performance to costume or prop design and technical theatre. Designed to mirror the full theatre pipeline, it helps learners discover their strengths across creative and technical roles through group projects. With real-world projects, external workshops, guest speakers and partnerships with local theatres and arts organisations, learners gain valuable experience and industry connections.</p>", "C_YEAR": "", "C_CREATED": "00:00:25", "C_CREATEDBY": "83439040", "C_UPDATED": "00:15:22", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Advanced (Level Three)"], "funding": []}, {"C_ID": "753", "C_TITLE": "Gateway Level 1 Award in Skills for Creative Industries (Art and Media)", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "<p>TBC</p>", "C_QUALIFICATION": "<p>Gateway Level 1 Award in Skills for Creative Industries (Art and Media)</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This Level 1 course, awarded by Gateway Qualifications, provides learners with a broad introduction to the creative industries while developing essential employability skills. During the course, learners will build their confidence in working as part of a team and develop communication skills for the workplace, helping prepare them for future study and employment.</p>\n\n<p>Learners will explore a range of creative disciplines including graphic design, digital photography, art and design, games design, fashion design and moving image. This variety allows learners to experiment with different creative processes, develop practical skills and begin to identify the areas they enjoy most. By the end of the course, learners will have gained a strong foundation in creative practice and transferable skills. This prepares them to progress onto a Level 2 qualification, where they can specialise further in either Art, Design and Fashion or Creative Media.</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Progress onto a Level 2 course in Art, Design and Fashion or Creative Media.</li>\n\t<li>Further progression to Level 3 creative courses such as Fashion Design, Visual Communications &amp; Styling, Film &amp; Photography, Games Design, Graphic Design, Animation &amp; Illustration.</li>\n\t<li>Build a creative portfolio to support applications for higher-level college courses or apprenticeships.</li>\n\t<li>Potential progression to creative apprenticeships in areas such as media, marketing, digital design or content creation.</li>\n\t<li>Long-term progression to university or specialist creative courses after completing higher-level qualifications.</li>\n</ul>", "C_ELIGIBILITY": "<p>Two grade 2 GCSEs (one in English or Maths and one in a related subject).</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Project-based coursework.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>There will be some cost as learners will need shared materials for the different modules.&nbsp;</p>", "C_FUNDING": "", "C_CONTACT": "<p>careersadvicezone@chelmsford.ac.uk</p>", "C_METADESC": "", "C_SEOTITLE": "Gateway Level 1 Award in Skills for Creative Industries (Art and Media)", "C_SEOH1": "Gateway Level 1 Award in Skills for Creative Industries (Art and Media) Essex", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This course is ideal for learners who are interested in exploring different areas of the creative industries and want to develop their practical and personal skills in a supportive environment.</p>\n\n<p>It is suitable if you enjoy being creative, experimenting with ideas and learning new digital and design skills. You may already have an interest in areas such as art, photography, fashion, games or media or you may still be discovering which creative pathway suits you best.</p>\n\n<p>This course may be right for you if you want to:</p>\n\n<ul>\n\t<li>Try a range of creative subjects before choosing a specialism</li>\n\t<li>Develop your confidence, communication and teamwork skills</li>\n\t<li>Learn practical skills in design, photography, digital media and creative projects</li>\n\t<li>Build a portfolio of work to support progression to a Level 2 creative course</li>\n</ul>\n\n<p>It is particularly suited to learners who prefer hands-on, project-based learning and want to develop both their creativity and their readiness for further study.</p>", "C_YEAR": "", "C_CREATED": "00:21:40", "C_CREATEDBY": "83439040", "C_UPDATED": "00:10:42", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Foundation (Level One)"], "funding": []}, {"C_ID": "755", "C_TITLE": "UAL Level 2 Award and Diploma in Creative Media Production and Technology (Creative Media)", "C_SECTION": "48", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "1 year", "C_DAYS": "<p>TBC</p>", "C_QUALIFICATION": "<p>UAL&nbsp;Level 2 Award and Diploma in&nbsp;Creative Media Production and Technology (Creative Media)</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>The UAL Level 2 Award and Diploma in Creative Media Production and Technology, awarded by University of the Arts London Awarding Body, is designed to introduce learners to a range of creative media skills and prepare them for further study in the creative industries.</p>\n\n<p>During the course, learners will explore different areas of creative media through rotations which allow learners to experience a variety of creative disciplines, develop practical skills and discover which area they would like to specialise in at Level 3.</p>\n\n<p>Learners will work on a range of creative projects and industry-style briefs, learning how to develop ideas, plan and produce media content and present their work professionally. The course focuses on building both technical skills and creative thinking, while also helping learners develop important transferable skills such as communication, teamwork and problem solving.</p>\n\n<p>By the end of the course, learners will have produced a portfolio of creative work that supports progression to Level 3 media courses in Film &amp; Photography, Graphic Design, Games Design or Animation &amp; Illustration.</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Progress onto a Level 3 course specialising in Film &amp; Photography, Graphic Design, Games Design or Animation &amp; Illustration.</li>\n\t<li>Further progression to higher-level creative courses such as Creative Media Production, Animation, Games Design, Graphic Design, Film Production&nbsp;or Photography.</li>\n\t<li>Build a creative portfolio to support applications for Level 3 courses, apprenticeships&nbsp;or further creative study.</li>\n\t<li>Potential progression to creative apprenticeships in areas such as media production, digital content creation, graphic design, marketing&nbsp;or photography.</li>\n</ul>\n\n<p>Long-term progression to university or specialist creative courses after completing higher-level qualifications in the creative industries.</p>", "C_ELIGIBILITY": "<p>Three grade 3 GCSEs (1 in English or Maths and 1 in a related subject) OR successful achievement of a Level 1 vocational course.</p>", "C_ELIGIBILITYSPECIFIC": "", "C_ASSESSMENT": "<p>Project-based coursework.</p>", "C_FEES": "", "C_ADDITIONALFEES": "<p>&pound;80 materials fee</p>", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "", "C_SEOH1": "", "C_SEOH2": "", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This course is ideal if you are interested in creative design and digital media and want to develop practical skills across a range of media disciplines before choosing a specialist pathway.</p>\n\n<p>During the course you will take part in rotations across three creative pathways:</p>\n\n<ul>\n\t<li>Graphics &amp; Illustration</li>\n\t<li>Games &amp; Animation</li>\n\t<li>Film &amp; Photography</li>\n</ul>\n\n<p>This allows you to explore different areas of the creative media industry, develop a wide range of skills and discover which area you enjoy most before progressing to a Level 3 specialism.</p>\n\n<p>You will work on a variety of creative projects, learning how to develop ideas, work in a team, respond to a brief, produce media content and present your work while building an understanding of the creative production process used in industry.</p>\n\n<p>This course may be right for you if you:</p>\n\n<ul>\n\t<li>Enjoy creative and digital media projects</li>\n\t<li>Want to try different creative pathways before specialising</li>\n\t<li>Are interested in areas such as design, animation, games, film, photography or digital media</li>\n\t<li>Prefer hands-on learning through practical projects</li>\n\t<li>Want to develop a portfolio of creative work for progression to Level 3</li>\n</ul>\n\n<p>It is particularly suited to learners who are creative, curious and willing to experiment with new ideas and technologies while developing the skills needed to progress within the creative media industries.</p>", "C_YEAR": "", "C_CREATED": "00:18:58", "C_CREATEDBY": "83439040", "C_UPDATED": "00:15:53", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Creative Industries", "levels": ["Intermediate (Level Two)"], "funding": []}, {"C_ID": "756", "C_TITLE": "NCFE CACHE Technical Occupational Entry in Social Care, Level 3", "C_SECTION": "13", "C_MODE": "FT", "C_APPTYPE": "", "C_DURATION": "2 years", "C_DAYS": "<p>Confirmed on enrolment&nbsp;</p>", "C_QUALIFICATION": "<p>NCFE CACHE Level 3 Technical Occupational Entry in Social Care (Diploma)</p>", "C_ADDITIONALQUALS": "", "C_COURSECODE": "", "C_SHORTCODE": "", "C_LEARNINGAIM": "", "C_LEVEL": "", "C_STARTDATE": "2026-09-01 00:00:00", "C_STUDYOVERVIEW": "<p>This full time Level 3 Social Care qualification is ideal for learners who want to begin a career in health and social care and make a real difference to people&rsquo;s lives. You will study key areas of adult care, completing 23 units that include working in social care, communication, safeguarding, mental health, learning disabilities, dementia, infection control and health and safety. The course combines classroom learning with practical experience, including a work placement, helping you develop the knowledge, skills and behaviours needed for roles within the industry. Assessment is through a portfolio of evidence rather than exams, making it a supportive route for learners who prefer continuous assessment.</p>", "C_EMPLOYABILITY": "<ul>\n\t<li>Learners who complete this qualification could progress to employment in the healthcare sector in roles such as such as Care Worker, Personal Assistant, Community Support Worker, Outreach Worker and Activities Co-Ordinator.</li>\n\t<li>Alternatively, you may wish to progress to higher level study such as a degree in social work, social care, health care, nursing or counselling.</li>\n\t<li>You could also progress to a higher level apprenticeship in a skilled profession such as Emergency Care Assistant or Health Care Worker.</li>\n</ul>", "C_ELIGIBILITY": "<ul>\n\t<li>4 GCSEs at grades 4-9 to including&nbsp;English Language</li>\n\t<li>Clear, fully enhanced DBS check</li>\n</ul>", "C_ELIGIBILITYSPECIFIC": "<ul>\n\t<li>GCSE grade 4-9 in English Language</li>\n\t<li>GCSE grade 3 in Maths</li>\n\t<li>Internal candidates must have successful completion of current course to meet course entry requirements and meet College expectations regarding attendance and attitude.</li>\n</ul>", "C_ASSESSMENT": "<ul>\n\t<li>This qualification is internally assessed through coursework and placement that builds up a portfolio of evidence. &nbsp;</li>\n\t<li>You will be required to complete 100 hours of placement over 2 years.</li>\n</ul>", "C_FEES": "", "C_ADDITIONALFEES": "<ul>\n\t<li>Uniform of polo shirts&nbsp;approximately &pound;10 each and sweatshirts approximately &pound;15 each&nbsp;must be purchased.</li>\n\t<li>Uniform must be worn in class and to placement.</li>\n\t<li>DBS check&nbsp;approximately &pound;50</li>\n\t<li>You will be required to purchase course textbooks&nbsp;which are essential for completing your studies.</li>\n\t<li>Enrichment activities thoughout&nbsp;the course are to be paid for as necessary.</li>\n</ul>", "C_FUNDING": "", "C_CONTACT": "", "C_METADESC": "", "C_SEOTITLE": "Level 3 Social Care Course Essex | Chelmsford College", "C_SEOH1": "Level 3 Diploma in Social Care - Chelmsford College", "C_SEOH2": "Level 3 Course in Social Care", "C_APPLYFORMTYPE": "", "C_COURSEFORME": "<p>This brand-new qualification for 2026 focuses on the social care sector and gives you a strong foundation of the knowledge, skills and behaviours needed to work in this rewarding field. You&rsquo;ll develop practical and technical skills while exploring a wide range of topics, from working in social care and supporting others to anatomy and physiology, dementia awareness, autism and end-of-life care.</p>\n\n<p>A key part of the course is completing 100 hours of work placement, providing you with real world experience in health or social care settings while you study. This hands-on experience will strengthen your CV, help you understand the industry first-hand and allow you to build valuable professional connections.</p>", "C_YEAR": "", "C_CREATED": "00:35:30", "C_CREATEDBY": "83439040", "C_UPDATED": "00:45:01", "C_UPDATEDBY": "83439040", "C_DELETED": "", "C_DELETEDBY": "", "C_PUBLISHED": "1", "section": "Health & Social Care", "levels": ["Advanced (Level Three)"], "funding": ["16-18"]}];